FROM json_to_recordset($TREINOS$[{"atualizado_em": "2026-09-18T02:24:31.425847+00:00", "avaliacao_obrigatoria": true, "categoria": "Segurança", "conteudo_html": "## Seção 1: Introdução à Segurança da Informação\n\n[Imagem: https://images.unsplash.com/photo-1555949963-ff9fe0c870eb?w=800&auto=format&fit=crop]\n\n[Vídeo: https://www.youtube.com/watch?v=hRQ4qSJdvYs]\n\nA **Segurança da Informação** é o conjunto de práticas, políticas e tecnologias destinadas a proteger informações contra acessos não autorizados, alterações indevidas, destruição ou vazamento.\n\n### Os Três Pilares da Segurança\n\n**Confidencialidade** - Garantir que a informação seja acessível apenas por pessoas autorizadas.\n\n**Integridade** - Assegurar que a informação não seja alterada de forma não autorizada.\n\n**Disponibilidade** - Garantir que a informação esteja disponível quando necessário.\n\n### Por que isso é importante para você?\n\n• Você lida diariamente com informações da empresa\n• Dados de clientes passam pelas suas mãos\n• Um único descuido pode causar grandes prejuízos\n• Você é a primeira linha de defesa\n\n---\n\n## Seção 2: Senhas Seguras\n\n[Imagem: https://images.unsplash.com/photo-1614064641938-3bbee52942c7?w=800&auto=format&fit=crop]\n\n### Como criar senhas fortes\n\nUma senha forte deve ter:\n• No mínimo 12 caracteres\n• Letras maiúsculas e minúsculas\n• Números\n• Caracteres especiais (!@#$%&*)\n\n**Exemplos de senhas FRACAS:**\n• 123456 (sequência numérica)\n• senha123 (palavra comum + números)\n• joao1985 (nome + data de nascimento)\n• qwerty (sequência do teclado)\n\n**Dicas para senhas FORTES:**\n• Use frases: \"MeuCachorro@Toby#2024!\"\n• Substitua letras: \"S3gur@nc@D@1nf0\"\n• Combine palavras: \"Café+Livro=Manhã2024\"\n\n### Práticas essenciais\n\n☑ Nunca compartilhe sua senha com ninguém\n☑ Não anote senhas em papéis ou post-its\n☑ Use senhas diferentes para cada sistema\n☑ Troque suas senhas periodicamente\n☑ Considere usar um gerenciador de senhas\n\n---\n\n## Seção 3: Identificando Phishing\n\n[Imagem: https://images.unsplash.com/photo-1563013544-824ae1b704d3?w=800&auto=format&fit=crop]\n\n[Vídeo: https://www.youtube.com/watch?v=UTBEbf2taD4]\n\n### O que é Phishing?\n\nPhishing é uma técnica de **engenharia social**.\n\nSeu objetivo é:\n*   Enganar você\n*   Obter suas informações confidenciais, como senhas e dados bancários.\n\n### Sinais de alerta em e-mails\n\n• **Remetente suspeito** - Endereços com erros ou domínios estranhos\n• **Urgência excessiva** - \"Sua conta será bloqueada em 24 horas!\"\n• **Erros gramaticais** - Textos mal escritos ou traduzidos\n• **Links suspeitos** - Passe o mouse para ver o endereço real\n• **Anexos inesperados** - Arquivos não solicitados\n• **Pedidos de dados pessoais** - Bancos não pedem senhas por e-mail\n\n### Exemplos de phishing comum\n\n1. **Falso banco:** \"Detectamos atividade suspeita, clique para verificar\"\n2. **Falsa empresa de entregas:** \"Sua encomenda está retida, pague a taxa\"\n3. **Falso TI:** \"Sua conta será desativada, atualize sua senha\"\n4. **Falso prêmio:** \"Você ganhou! Clique para resgatar\"\n\n### O que fazer ao receber um e-mail suspeito?\n\n• Não clique em links\n• Não abra anexos\n• Não responda\n• Reporte ao time de TI\n• Delete o e-mail\n\n---\n\n## Seção 4: Uso Seguro de Dispositivos\n\n[Imagem: https://images.unsplash.com/photo-1496181133206-80ce9b88a853?w=800&auto=format&fit=crop]\n\n### No computador\n\n• **Bloqueie a tela** ao se ausentar (Windows+L ou Ctrl+Cmd+Q)\n• **Mantenha o sistema atualizado** com os patches de segurança\n• **Use apenas softwares autorizados** pela empresa\n• **Faça backup regular** dos seus arquivos importantes\n• **Não conecte dispositivos USB** desconhecidos\n\n### No celular corporativo\n\n• Configure bloqueio de tela com PIN ou biometria\n• Não instale aplicativos de fontes desconhecidas\n• Evite redes Wi-Fi públicas\n• Mantenha o dispositivo sempre atualizado\n• Ative a localização remota\n\n---\n\n## Seção 5: Redes Wi-Fi e VPN\n\n[Imagem: https://images.unsplash.com/photo-1544197150-b99a580bb7a8?w=800&auto=format&fit=crop]\n\n### Riscos das redes Wi-Fi públicas\n\nRedes públicas (cafés, aeroportos, hotéis) são vulneráveis a ataques:\n\n• **Man-in-the-middle** - Interceptação de dados\n• **Redes falsas** - Hackers criam redes com nomes similares\n• **Sniffing** - Captura de tráfego não criptografado\n\n### Quando usar VPN?\n\nSempre que precisar acessar dados da empresa fora do escritório:\n\n• Trabalho remoto (home office)\n• Viagens de negócios\n• Acesso a sistemas internos\n• Qualquer rede Wi-Fi pública\n\n---\n\n## Seção 6: Conclusão e Boas Práticas\n\n[Imagem: https://images.unsplash.com/photo-1573164713988-8665fc963095?w=800&auto=format&fit=crop]\n\n### Resumo das boas práticas\n\n☑ Use senhas fortes e únicas\n☑ Identifique e reporte phishing\n☑ Mantenha dispositivos seguros\n☑ Use VPN em redes públicas\n☑ Bloqueie a tela ao se ausentar\n☑ Reporte incidentes imediatamente\n\n**Você é a primeira linha de defesa!**\n\nA segurança da informação depende de cada um de nós. Pratique esses conhecimentos diariamente.", "criado_em": "2026-01-30T13:44:48.125863+00:00", "data_limite": null, "departamento_id": null, "descricao": "Treinamento essencial sobre práticas de segurança da informação, incluindo proteção de senhas, identificação de phishing, uso seguro de dispositivos e boas práticas no ambiente digital.", "duracao_minutos": 30, "empresa_id": null, "id": "56ad682c-1bb6-4cff-92cf-cb1991fd3a53", "instrutor_id": null, "media_avaliacao": 0, "nivel": "basico", "nota_minima": 7, "obrigatorio": true, "publicado": false, "tempo_avaliacao_minutos": 20, "thumbnail_url": "https://images.unsplash.com/photo-1555949963-ff9fe0c870eb?w=800&auto=format&fit=crop", "titulo": "Segurança da Informação para Colaboradores", "total_avaliacoes": 0}, {"atualizado_em": "2026-09-18T02:26:34.379901+00:00", "avaliacao_obrigatoria": true, "categoria": "Liderança", "conteudo_html": "## Seção 1: A Importância da Comunicação\n\n[Imagem: https://images.unsplash.com/photo-1573497019940-1c28c88b4f3e?w=800&auto=format&fit=crop]\n\n[Vídeo: https://www.youtube.com/watch?v=N7Y36aVla18]\n\nA **comunicação eficaz** é uma das habilidades mais valorizadas no ambiente de trabalho. Estudos mostram que problemas de comunicação estão entre as principais causas de conflitos e ineficiências nas organizações.\n\n### Por que Comunicação Importa?\n\n• 70% do tempo de trabalho envolve comunicação\n• Mal-entendidos custam tempo e dinheiro\n• Boa comunicação aumenta a produtividade\n• Fortalece relacionamentos profissionais\n• Reduz conflitos e estresse\n\n---\n\n## Seção 2: Elementos da Comunicação\n\n[Imagem: https://images.unsplash.com/photo-1522071820081-009f0129c71c?w=800&auto=format&fit=crop]\n\n### O Processo de Comunicação\n\n1. **Emissor** - Quem envia a mensagem\n2. **Mensagem** - O conteúdo transmitido\n3. **Canal** - O meio utilizado\n4. **Receptor** - Quem recebe a mensagem\n5. **Feedback** - A resposta do receptor\n\n### Barreiras à Comunicação\n\n• Ruídos físicos (barulho, ambiente)\n• Filtros perceptuais (preconceitos, suposições)\n• Diferenças culturais\n• Jargões técnicos\n• Estado emocional\n• Falta de atenção\n\n---\n\n## Seção 3: Escuta Ativa\n\n[Imagem: https://images.unsplash.com/photo-1552581234-26160f608093?w=800&auto=format&fit=crop]\n\n[Vídeo: https://www.youtube.com/watch?v=n__kjaXoMFM]\n\n### O que é Escuta Ativa?\n\nÉ ouvir de forma completa e consciente, demonstrando interesse genuíno no que o outro está dizendo.\n\n### Técnicas de Escuta Ativa\n\n☑ Mantenha contato visual\n☑ Não interrompa\n☑ Faça perguntas esclarecedoras\n☑ Parafraseie para confirmar entendimento\n☑ Observe a linguagem corporal\n☑ Evite julgar prematuramente\n☑ Desligue distrações (celular, computador)\n\n### Frases Úteis\n\n• \"Se entendi bem, você está dizendo que...\"\n• \"Pode me dar um exemplo?\"\n• \"Como você se sente em relação a isso?\"\n• \"O que você sugere como solução?\"\n\n---\n\n## Seção 4: Comunicação Assertiva\n\n[Imagem: https://images.unsplash.com/photo-1573164713988-8665fc963095?w=800&auto=format&fit=crop]\n\n### Estilos de Comunicação\n\n**Passivo:** Evita conflitos, não expressa opinião\n**Agressivo:** Impõe opinião, desrespeita o outro\n**Passivo-Agressivo:** Concorda na frente, critica pelas costas\n**Assertivo:** Expressa opinião com respeito\n\n### Como ser Assertivo\n\n• Use \"eu\" ao invés de \"você\" (Eu sinto vs. Você me faz)\n• Seja específico e direto\n• Mantenha tom de voz equilibrado\n• Respeite o ponto de vista do outro\n• Proponha soluções\n\n---\n\n## Seção 5: Feedback Construtivo\n\n[Imagem: https://images.unsplash.com/photo-1531482615713-2afd69097998?w=800&auto=format&fit=crop]\n\n### Dando Feedback\n\n**Modelo DESC:**\n• **D**escreva a situação objetivamente\n• **E**xpresse como você se sente/percebe\n• **S**olicite mudança específica\n• **C**onsequências (positivas) da mudança\n\n### Recebendo Feedback\n\n☑ Ouça sem interromper\n☑ Não fique na defensiva\n☑ Peça exemplos específicos\n☑ Agradeça pela contribuição\n☑ Reflita antes de responder\n\n---\n\n## Seção 6: Comunicação Escrita\n\n[Imagem: https://images.unsplash.com/photo-1516321318423-f06f85e504b3?w=800&auto=format&fit=crop]\n\n### E-mails Profissionais\n\n• Assunto claro e objetivo\n• Saudação apropriada\n• Mensagem estruturada (início, meio, fim)\n• Uma ideia principal por parágrafo\n• Revisão antes de enviar\n• Assinatura profissional\n\n### Erros Comuns\n\n• Usar \"CAPS LOCK\" (parece gritar)\n• Copiar pessoas desnecessariamente\n• Textos muito longos\n• Falta de revisão ortográfica\n• Responder a todos sem necessidade\n\n---\n\n## Seção 7: Conclusão\n\n[Imagem: https://images.unsplash.com/photo-1552664730-d307ca884978?w=800&auto=format&fit=crop]\n\n### Resumo das Boas Práticas\n\n☑ Pratique escuta ativa\n☑ Seja assertivo\n☑ Adapte sua comunicação ao público\n☑ Dê e receba feedback construtivo\n☑ Revise comunicações escritas\n☑ Observe a linguagem não-verbal\n\n**A comunicação é uma habilidade que se desenvolve com prática diária.**\n\nParabéns por completar este treinamento!", "criado_em": "2026-01-30T13:44:48.125863+00:00", "data_limite": null, "departamento_id": null, "descricao": "Desenvolva habilidades de comunicação interpessoal, aprenda técnicas de escuta ativa, feedback construtivo e comunicação assertiva para melhorar o relacionamento profissional.", "duracao_minutos": 90, "empresa_id": null, "id": "813bf205-27a9-4366-b7f4-dd358718ddb2", "instrutor_id": null, "media_avaliacao": 0, "nivel": "intermediario", "nota_minima": 7, "obrigatorio": false, "publicado": false, "tempo_avaliacao_minutos": 20, "thumbnail_url": "https://images.unsplash.com/photo-1573497019940-1c28c88b4f3e?w=800&auto=format&fit=crop", "titulo": "Comunicação Eficaz no Ambiente de Trabalho", "total_avaliacoes": 0}, {"atualizado_em": "2026-09-18T02:26:34.379901+00:00", "avaliacao_obrigatoria": true, "categoria": "Saúde", "conteudo_html": "## Seção 1: A Importância da Saúde Mental\n\n[Imagem: https://images.unsplash.com/photo-1544367567-0f2fcb009e0b?w=800&auto=format&fit=crop]\n\n[Vídeo: https://www.youtube.com/watch?v=QTLo4fmjLBU]\n\nA **saúde mental** é tão importante quanto a saúde física. Ela afeta como pensamos, sentimos e agimos no dia a dia, influenciando nossa capacidade de lidar com o estresse, relacionar-se com outros e tomar decisões.\n\n### Dados sobre Saúde Mental no Trabalho\n\n• Transtornos mentais são a 3ª causa de afastamento\n• 1 em cada 4 pessoas terá algum transtorno mental\n• Depressão e ansiedade custam US$1 trilhão/ano globalmente\n• Investir em saúde mental dá retorno de 4:1\n\n---\n\n## Seção 2: Sinais de Alerta\n\n[Imagem: https://images.unsplash.com/photo-1493836512294-502baa1986e2?w=800&auto=format&fit=crop]\n\n### Reconheça os Sinais\n\n**Físicos:**\n• Cansaço constante\n• Dores de cabeça frequentes\n• Alterações no sono\n• Mudanças no apetite\n• Tensão muscular\n\n**Emocionais:**\n• Irritabilidade excessiva\n• Tristeza persistente\n• Ansiedade sem motivo aparente\n• Dificuldade de concentração\n• Sensação de vazio\n\n**Comportamentais:**\n• Isolamento social\n• Queda de produtividade\n• Procrastinação\n• Uso excessivo de álcool/substâncias\n• Negligência com autocuidado\n\n---\n\n## Seção 3: Gerenciamento do Estresse\n\n[Imagem: https://images.unsplash.com/photo-1506126613408-eca07ce68773?w=800&auto=format&fit=crop]\n\n[Vídeo: https://www.youtube.com/watch?v=MQGTDXfXR7Q]\n\n### O que é Estresse?\n\nResposta natural do corpo a situações desafiadoras. Pode ser positivo (eustresse) ou negativo (distresse).\n\n### Técnicas para Gerenciar\n\n**Respiração 4-7-8:**\n1. Inspire por 4 segundos\n2. Segure por 7 segundos\n3. Expire por 8 segundos\n4. Repita 4x\n\n**Técnica do Grounding (5-4-3-2-1):**\n• 5 coisas que você VÊ\n• 4 coisas que você TOCA\n• 3 coisas que você OUVE\n• 2 coisas que você CHEIRA\n• 1 coisa que você SABOREIA\n\n---\n\n## Seção 4: Mindfulness no Trabalho\n\n[Imagem: https://images.unsplash.com/photo-1508672019048-805c876b67e2?w=800&auto=format&fit=crop]\n\n### O que é Mindfulness?\n\nÉ a prática de estar plenamente presente no momento atual, com atenção e sem julgamento.\n\n### Práticas Simples para o Dia a Dia\n\n☑ **Meditação de 5 minutos** pela manhã\n☑ **Pausas conscientes** entre tarefas\n☑ **Comer sem distrações** (sem celular/computador)\n☑ **Caminhada atenta** percebendo sensações\n☑ **Respiração consciente** em momentos de tensão\n\n### Benefícios Comprovados\n\n• Redução de ansiedade\n• Melhora na concentração\n• Melhor regulação emocional\n• Aumento da criatividade\n• Melhora nos relacionamentos\n\n---\n\n## Seção 5: Equilíbrio Vida-Trabalho\n\n[Imagem: https://images.unsplash.com/photo-1507679799987-c73779587ccf?w=800&auto=format&fit=crop]\n\n### Estabelecendo Limites\n\n• Defina horários de início e término\n• Desconecte-se após o expediente\n• Aprenda a dizer \"não\"\n• Priorize o que é importante vs. urgente\n• Tire férias (de verdade!)\n\n### Cuidados Essenciais\n\n☑ **Sono de qualidade** (7-8 horas)\n☑ **Alimentação balanceada**\n☑ **Exercícios físicos** regulares\n☑ **Momentos de lazer**\n☑ **Conexões sociais** significativas\n\n---\n\n## Seção 6: Buscando Ajuda\n\n[Imagem: https://images.unsplash.com/photo-1573497019940-1c28c88b4f3e?w=800&auto=format&fit=crop]\n\n### Quando Buscar Ajuda Profissional?\n\n• Sintomas persistentes por mais de 2 semanas\n• Dificuldade em realizar atividades cotidianas\n• Pensamentos de automutilação\n• Uso de substâncias para lidar com problemas\n• Quando você sentir que precisa\n\n### Recursos Disponíveis\n\n• **CVV:** 188 (24 horas, gratuito)\n• Psicólogos e psiquiatras\n• RH da empresa (programas de apoio)\n• Grupos de apoio\n• Apps de meditação (Headspace, Calm)\n\n---\n\n## Seção 7: Conclusão\n\n[Imagem: https://images.unsplash.com/photo-1552664730-d307ca884978?w=800&auto=format&fit=crop]\n\n### Lembre-se\n\n☑ Cuidar da saúde mental não é fraqueza\n☑ Pedir ajuda é sinal de coragem\n☑ Pequenas práticas diárias fazem diferença\n☑ Você não está sozinho\n☑ A recuperação é possível\n\n**\"Não há saúde sem saúde mental.\"** - OMS\n\nParabéns por completar este treinamento sobre Saúde Mental!", "criado_em": "2026-01-30T13:44:48.125863+00:00", "data_limite": null, "departamento_id": null, "descricao": "Aprenda sobre a importância da saúde mental, técnicas de gerenciamento do estresse, mindfulness e como manter o equilíbrio entre vida pessoal e profissional.", "duracao_minutos": 90, "empresa_id": null, "id": "129b5064-72fd-4a0b-9d1e-76bd84bee471", "instrutor_id": null, "media_avaliacao": 0, "nivel": "basico", "nota_minima": 7, "obrigatorio": false, "publicado": false, "tempo_avaliacao_minutos": 20, "thumbnail_url": null, "titulo": "Saúde Mental e Bem-Estar no Trabalho", "total_avaliacoes": 0}, {"atualizado_em": "2026-08-30T11:54:27.511355+00:00", "avaliacao_obrigatoria": true, "categoria": "Técnico", "conteudo_html": "## Seção 1: Introdução ao Excel\n\n[Imagem: https://images.unsplash.com/photo-1460925895917-afdab827c52f?w=800&auto=format&fit=crop]\n\nO **Microsoft Excel** é uma das ferramentas mais utilizadas no mundo corporativo. Dominar suas funcionalidades pode aumentar significativamente sua produtividade e valor profissional.\n\n### Interface Básica\n\n• **Células** - Interseção de linhas e colunas (ex: A1, B2)\n• **Planilha** - Conjunto de células\n• **Pasta de Trabalho** - Arquivo com várias planilhas\n• **Faixa de Opções** - Menus com ferramentas\n• **Barra de Fórmulas** - Onde inserimos fórmulas\n\n---\n\n## Seção 2: Fórmulas Essenciais\n\n[Imagem: https://images.unsplash.com/photo-1504868584819-f8e8b4b6d7e3?w=800&auto=format&fit=crop]\n\n### Operadores Básicos\n\n• **+** Adição\n• **-** Subtração\n• ***** Multiplicação\n• **/** Divisão\n• **^** Potência\n\n### Fórmulas Mais Usadas\n\n**SOMA:** =SOMA(A1:A10)\nSoma todos os valores do intervalo\n\n**MÉDIA:** =MÉDIA(A1:A10)\nCalcula a média dos valores\n\n**MÁXIMO/MÍNIMO:** =MÁXIMO(A1:A10)\nEncontra o maior/menor valor\n\n**CONT.VALORES:** =CONT.VALORES(A1:A10)\nConta células não vazias\n\n---\n\n## Seção 3: Funções de Pesquisa\n\n[Imagem: https://images.unsplash.com/photo-1551288049-bebda4e38f71?w=800&auto=format&fit=crop]\n\n### PROCV (VLOOKUP)\n\nProcura um valor na primeira coluna e retorna um valor da mesma linha:\n\n=PROCV(valor_procurado; tabela; coluna_resultado; [falso])\n\n**Exemplo:**\n=PROCV(A2;Produtos!A:C;3;FALSO)\n\n### PROCH (HLOOKUP)\n\nSimilar ao PROCV, mas procura em linhas horizontais.\n\n### PROCX (Versão Moderna)\n\n=PROCX(valor_procurado; intervalo_procura; intervalo_retorno)\n\n---\n\n## Seção 4: Formatação Condicional\n\n[Imagem: https://images.unsplash.com/photo-1543286386-713bdd548da4?w=800&auto=format&fit=crop]\n\n### O que é?\n\nAltera automaticamente a aparência das células com base em regras definidas.\n\n### Casos de Uso\n\n☑ Destacar valores acima/abaixo da média\n☑ Criar escalas de cores (semáforo)\n☑ Barras de dados para visualização\n☑ Identificar duplicatas\n☑ Destacar datas vencidas\n\n### Como Aplicar\n\n1. Selecione o intervalo\n2. Página Inicial > Formatação Condicional\n3. Escolha a regra desejada\n4. Defina o formato\n\n---\n\n## Seção 5: Tabelas Dinâmicas\n\n[Imagem: https://images.unsplash.com/photo-1551288049-bebda4e38f71?w=800&auto=format&fit=crop]\n\n### O que são?\n\nFerramenta poderosa para resumir, analisar e apresentar grandes volumes de dados.\n\n### Como Criar\n\n1. Selecione seus dados\n2. Inserir > Tabela Dinâmica\n3. Escolha onde criar\n4. Arraste campos para as áreas:\n   - Filtros\n   - Colunas\n   - Linhas\n   - Valores\n\n### Dicas\n\n• Seus dados devem ter cabeçalhos\n• Evite células vazias\n• Atualize a tabela após mudanças nos dados\n• Use segmentação de dados para filtros visuais\n\n---\n\n## Seção 6: Gráficos\n\n[Imagem: https://images.unsplash.com/photo-1460925895917-afdab827c52f?w=800&auto=format&fit=crop]\n\n### Tipos de Gráficos\n\n**Colunas/Barras:** Comparar valores\n**Linhas:** Mostrar tendências ao longo do tempo\n**Pizza:** Mostrar proporções do todo\n**Dispersão:** Correlação entre variáveis\n**Combinados:** Dois tipos no mesmo gráfico\n\n### Boas Práticas\n\n☑ Escolha o tipo adequado aos dados\n☑ Adicione títulos claros\n☑ Rotule os eixos\n☑ Evite poluição visual\n☑ Use cores com propósito\n\n---\n\n## Seção 7: Atalhos Úteis\n\n[Imagem: https://images.unsplash.com/photo-1496181133206-80ce9b88a853?w=800&auto=format&fit=crop]\n\n### Atalhos Essenciais\n\n• **Ctrl+C/V/X** - Copiar/Colar/Recortar\n• **Ctrl+Z** - Desfazer\n• **Ctrl+S** - Salvar\n• **Ctrl+Home** - Ir para A1\n• **Ctrl+End** - Ir para última célula usada\n• **Ctrl+Seta** - Navegar entre dados\n• **F2** - Editar célula\n• **Alt+=** - AutoSoma\n• **Ctrl+Shift+L** - Filtros\n\n---\n\n## Seção 8: Conclusão\n\nO Excel é uma ferramenta vasta. Continue praticando e explorando novas funcionalidades.\n\n**Próximos passos:**\n• Pratique com dados reais\n• Explore funções SE, SOMASES, CONT.SES\n• Aprenda sobre macros e VBA\n• Experimente Power Query\n\nParabéns por completar este treinamento!", "criado_em": "2026-01-30T13:44:48.125863+00:00", "data_limite": null, "departamento_id": "d5d9e776-abbc-4c1e-bee7-850bcee9529f", "descricao": "Domine as principais funcionalidades do Excel: fórmulas, funções, tabelas dinâmicas, gráficos e formatação para otimizar suas tarefas diárias.", "duracao_minutos": 30, "empresa_id": "012f817c-3197-4f5d-8506-4f03e12b0edd", "id": "b26b7ca9-2ae9-43a2-84d3-a173063f9f39", "instrutor_id": "6c42cbcf-2180-4523-9551-59b97f5359ad", "media_avaliacao": 0, "nivel": null, "nota_minima": 7, "obrigatorio": false, "publicado": true, "tempo_avaliacao_minutos": 0, "thumbnail_url": "https://images.unsplash.com/photo-1460925895917-afdab827c52f?w=800&auto=format&fit=crop", "titulo": "Excel Básico ao Intermediário", "total_avaliacoes": 0}, {"atualizado_em": "2026-09-17T09:21:23.452777+00:00", "avaliacao_obrigatoria": false, "categoria": "Desenvolvimento Pessoal", "conteudo_html": "## Seção 1: Por que Trabalhar em Equipe?\n\n[Imagem: https://images.unsplash.com/photo-1522071820081-009f0129c71c?w=800&auto=format&fit=crop]\n\nO **trabalho em equipe** é fundamental no ambiente corporativo moderno. Equipes bem integradas alcançam resultados superiores ao que indivíduos conseguiriam sozinhos.\n\n### Benefícios do Trabalho em Equipe\n\n• Complementaridade de habilidades\n• Maior criatividade e inovação\n• Divisão de carga de trabalho\n• Aprendizado mútuo\n• Suporte emocional\n• Melhores resultados\n\n---\n\n## Seção 2: Características de Equipes de Sucesso\n\n[Imagem: https://images.unsplash.com/photo-1552664730-d307ca884978?w=800&auto=format&fit=crop]\n\n### Elementos Essenciais\n\n**Objetivo Comum:**\nTodos conhecem e compartilham a meta do time.\n\n**Comunicação Aberta:**\nAmbiente onde todos podem expressar ideias.\n\n**Confiança Mútua:**\nMembros confiam uns nos outros.\n\n**Papéis Claros:**\nCada um sabe sua responsabilidade.\n\n**Respeito às Diferenças:**\nDiversidade é valorizada.\n\n---\n\n## Seção 3: Colaboração Efetiva\n\n[Imagem: https://images.unsplash.com/photo-1573164713988-8665fc963095?w=800&auto=format&fit=crop]\n\n### Práticas de Colaboração\n\n☑ Compartilhe informações proativamente\n☑ Ofereça ajuda antes de ser pedido\n☑ Peça ajuda quando necessário\n☑ Reconheça as contribuições dos outros\n☑ Celebre vitórias em conjunto\n\n### Ferramentas Colaborativas\n\n• Slack, Teams (comunicação)\n• Trello, Asana (gestão de projetos)\n• Google Drive, SharePoint (documentos)\n• Miro, Figma (colaboração visual)\n• Zoom, Meet (videoconferências)\n\n---\n\n## Seção 4: Resolução de Conflitos\n\n[Imagem: https://images.unsplash.com/photo-1573497019940-1c28c88b4f3e?w=800&auto=format&fit=crop]\n\n### Conflitos são Normais\n\nConflitos surgem quando pessoas com diferentes perspectivas trabalham juntas. O importante é como lidamos com eles.\n\n### Abordagem Construtiva\n\n1. **Identifique** o problema real\n2. **Escute** todos os lados\n3. **Foque** em interesses, não posições\n4. **Busque** soluções ganha-ganha\n5. **Comprometa-se** com a solução\n\n### O que Evitar\n\n• Atacar pessoas, não ideias\n• Evitar o conflito completamente\n• Querer \"ganhar\" a qualquer custo\n• Guardar ressentimentos\n• Falar pelas costas\n\n---\n\n## Seção 5: Dinâmicas de Grupo\n\n[Imagem: https://images.unsplash.com/photo-1519389950473-47ba0277781c?w=800&auto=format&fit=crop]\n\n### Estágios de Desenvolvimento (Tuckman)\n\n**1. Forming (Formação)**\nMembros se conhecem, há polidez e incerteza.\n\n**2. Storming (Conflito)**\nSurgem divergências e disputas por poder.\n\n**3. Norming (Normalização)**\nEstabelecem-se regras e acordos.\n\n**4. Performing (Desempenho)**\nEquipe funciona em alta performance.\n\n**5. Adjourning (Encerramento)**\nProjeto termina, equipe se dissolve.\n\n---\n\n## Seção 6: Seu Papel na Equipe\n\n[Imagem: https://images.unsplash.com/photo-1531482615713-2afd69097998?w=800&auto=format&fit=crop]\n\n### Papéis de Belbin\n\n• **Implementador** - Transforma ideias em ação\n• **Coordenador** - Facilita decisões\n• **Modelador** - Dá direção e foco\n• **Pensador** - Traz ideias criativas\n• **Explorador** - Busca recursos externos\n• **Monitor** - Avalia criticamente\n• **Agregador** - Une o time\n• **Finalizador** - Garante qualidade\n• **Especialista** - Traz conhecimento técnico\n\n### Conhecer seu Estilo\n\nEntender seu papel natural ajuda a contribuir melhor e complementar os outros.\n\n---\n\n## Seção 7: Conclusão\n\n[Imagem: https://images.unsplash.com/photo-1600880292203-757bb62b4baf?w=800&auto=format&fit=crop]\n\n### Resumo das Boas Práticas\n\n☑ Comunique-se de forma clara e respeitosa\n☑ Contribua com suas habilidades únicas\n☑ Apoie seus colegas\n☑ Resolva conflitos de forma construtiva\n☑ Celebre conquistas em equipe\n☑ Busque feedback e melhore continuamente\n\n**\"Sozinhos podemos fazer tão pouco; juntos podemos fazer muito.\"** - Helen Keller\n\nParabéns por completar este treinamento!", "criado_em": "2026-01-30T13:44:48.125863+00:00", "data_limite": null, "departamento_id": null, "descricao": "Aprenda a trabalhar de forma colaborativa, entenda dinâmicas de grupo, resolução de conflitos e como contribuir para um ambiente de trabalho harmonioso.", "duracao_minutos": 60, "empresa_id": null, "id": "1f352510-0c60-45b1-9de7-5cf35ed39ea8", "instrutor_id": null, "media_avaliacao": 0, "nivel": "basico", "nota_minima": 7, "obrigatorio": false, "publicado": false, "tempo_avaliacao_minutos": 0, "thumbnail_url": null, "titulo": "Trabalho em Equipe e Colaboração", "total_avaliacoes": 0}, {"atualizado_em": "2026-09-17T09:21:23.452777+00:00", "avaliacao_obrigatoria": false, "categoria": "Compliance", "conteudo_html": "## Seção 1: O que é a LGPD?\n\n[Imagem: https://images.unsplash.com/photo-1563013544-824ae1b704d3?w=800&auto=format&fit=crop]\n\nA **Lei Geral de Proteção de Dados (LGPD)** - Lei nº 13.709/2018 - é a legislação brasileira que regulamenta o tratamento de dados pessoais por pessoas físicas e jurídicas, públicas ou privadas.\n\n### Por que a LGPD foi criada?\n\nA LGPD surgiu em um contexto global de preocupação com a privacidade e a proteção dos dados pessoais dos cidadãos. Com o avanço da tecnologia e a digitalização de praticamente todos os aspectos da vida moderna, tornou-se essencial criar mecanismos legais para proteger as informações das pessoas.\n\n**Principais motivações:**\n• Aumento exponencial da coleta de dados pessoais\n• Escândalos de vazamento de dados em grandes empresas\n• Necessidade de harmonização com legislações internacionais (como o GDPR europeu)\n• Proteção dos direitos fundamentais de liberdade e privacidade\n\n---\n\n## Seção 2: Conceitos Fundamentais\n\n[Imagem: https://images.unsplash.com/photo-1516321318423-f06f85e504b3?w=800&auto=format&fit=crop]\n\n### O que são Dados Pessoais?\n\nDado pessoal é toda informação relacionada a uma pessoa natural identificada ou identificável. Isso inclui:\n\n• **Nome completo** - O identificador mais básico\n• **CPF, RG, CNH** - Documentos de identificação\n• **Endereço** - Residencial ou comercial\n• **E-mail** - Pessoal ou profissional\n• **Telefone** - Fixo ou celular\n• **Dados de localização** - GPS, check-ins\n• **Endereço IP** - Identificação na internet\n• **Cookies** - Rastreamento de navegação\n\n### Dados Pessoais Sensíveis\n\nSão dados que requerem proteção especial por revelarem aspectos íntimos da pessoa:\n\n☑ Origem racial ou étnica\n☑ Convicções religiosas\n☑ Opiniões políticas\n☑ Filiação sindical\n☑ Dados de saúde\n☑ Dados genéticos e biométricos\n☑ Orientação sexual\n\n**Importante:** O tratamento de dados sensíveis só é permitido com consentimento específico e destacado do titular ou nas hipóteses previstas em lei.\n\n---\n\n## Seção 3: Quem são os Agentes de Tratamento?\n\n[Imagem: https://images.unsplash.com/photo-1600880292203-757bb62b4baf?w=800&auto=format&fit=crop]\n\n### Controlador\n\nO **controlador** é a pessoa natural ou jurídica, de direito público ou privado, a quem competem as decisões referentes ao tratamento de dados pessoais.\n\n**Responsabilidades do Controlador:**\n• Definir as finalidades do tratamento\n• Determinar os meios de tratamento\n• Garantir a segurança dos dados\n• Atender aos direitos dos titulares\n\n### Operador\n\nO **operador** é a pessoa natural ou jurídica, de direito público ou privado, que realiza o tratamento de dados pessoais em nome do controlador.\n\n### Encarregado (DPO)\n\nO **Encarregado de Proteção de Dados** (Data Protection Officer - DPO) é a pessoa indicada pelo controlador para atuar como canal de comunicação entre o controlador, os titulares dos dados e a ANPD.\n\n---\n\n## Seção 4: Direitos dos Titulares\n\n[Imagem: https://images.unsplash.com/photo-1554224155-6726b3ff858f?w=800&auto=format&fit=crop]\n\nA LGPD garante diversos direitos aos titulares dos dados:\n\n1. **Confirmação e Acesso** - O titular pode confirmar a existência de tratamento e acessar seus dados pessoais.\n\n2. **Correção** - Direito de solicitar a correção de dados incompletos, inexatos ou desatualizados.\n\n3. **Anonimização, Bloqueio ou Eliminação** - Possibilidade de solicitar que dados desnecessários sejam anonimizados, bloqueados ou eliminados.\n\n4. **Portabilidade** - Direito de receber os dados para transferência a outro fornecedor de serviço.\n\n5. **Eliminação** - Solicitar a eliminação dos dados pessoais tratados com consentimento.\n\n6. **Revogação do Consentimento** - Retirar o consentimento a qualquer momento.\n\n---\n\n## Seção 5: Bases Legais para Tratamento\n\n[Imagem: https://images.unsplash.com/photo-1450101499163-c8848c66ca85?w=800&auto=format&fit=crop]\n\nPara que o tratamento de dados pessoais seja lícito, deve estar fundamentado em uma das seguintes bases legais:\n\n1. **Consentimento do titular** - Manifestação livre, informada e inequívoca\n2. **Cumprimento de obrigação legal** - Quando exigido por lei\n3. **Execução de políticas públicas** - Pela administração pública\n4. **Estudos por órgão de pesquisa** - Com anonimização quando possível\n5. **Execução de contrato** - Quando necessário para o contrato\n6. **Exercício regular de direitos** - Em processos judiciais\n7. **Proteção da vida** - Do titular ou de terceiro\n8. **Tutela da saúde** - Procedimentos realizados por profissionais da saúde\n9. **Legítimo interesse** - Do controlador ou terceiro\n10. **Proteção do crédito** - Conforme legislação pertinente\n\n---\n\n## Seção 6: Boas Práticas no Dia a Dia\n\n[Imagem: https://images.unsplash.com/photo-1551434678-e076c223a692?w=800&auto=format&fit=crop]\n\n### Como aplicar a LGPD na prática corporativa:\n\n**No trabalho remoto:**\n• Use apenas dispositivos autorizados pela empresa\n• Evite redes Wi-Fi públicas para acessar dados sensíveis\n• Mantenha a tela bloqueada quando se ausentar\n• Não compartilhe credenciais de acesso\n\n**No atendimento ao cliente:**\n• Colete apenas dados estritamente necessários\n• Informe claramente a finalidade da coleta\n• Registre o consentimento quando aplicável\n• Mantenha os dados atualizados\n\n**Na comunicação:**\n• Cuidado ao enviar e-mails com dados pessoais\n• Verifique os destinatários antes de enviar\n• Use cópia oculta (CCO) para múltiplos destinatários\n\n---\n\n## Seção 7: Sanções e Penalidades\n\n[Imagem: https://images.unsplash.com/photo-1589829545856-d10d557cf95f?w=800&auto=format&fit=crop]\n\nA LGPD prevê sanções administrativas para infrações:\n\n• **Advertência** - Com prazo para adoção de medidas corretivas\n• **Multa simples** - Até 2% do faturamento, limitada a R$ 50 milhões por infração\n• **Multa diária** - Observado o limite total\n• **Publicização da infração** - Após apuração confirmada\n• **Bloqueio dos dados** - Até regularização\n• **Eliminação dos dados** - Referentes à infração\n\n---\n\n## Seção 8: Avaliação Final\n\nAgora que você completou o estudo, reflita sobre os seguintes pontos:\n\n☑ Consigo identificar dados pessoais e dados sensíveis?\n☑ Sei quais são os direitos dos titulares?\n☑ Conheço as bases legais para tratamento?\n☑ Aplico boas práticas no meu dia a dia?\n\n**Parabéns por completar este treinamento!**\n\nA proteção de dados é responsabilidade de todos. Continue aplicando esses conhecimentos e ajude a construir uma cultura de privacidade na organização.", "criado_em": "2026-01-30T13:44:48.125863+00:00", "data_limite": null, "departamento_id": null, "descricao": "## Seção 1\n\nAprenda os fundamentos da Lei Geral de Proteção de Dados e como aplicá-la no dia a dia corporativo. Este treinamento aborda os principais conceitos, direitos dos titulares e obrigações das empresas.", "duracao_minutos": 60, "empresa_id": null, "id": "f4d82755-153a-4eb9-af85-e6b8c6c5df44", "instrutor_id": null, "media_avaliacao": 0, "nivel": "basico", "nota_minima": 7, "obrigatorio": true, "publicado": false, "tempo_avaliacao_minutos": 0, "thumbnail_url": "https://images.unsplash.com/photo-1563013544-824ae1b704d3?w=800&auto=format&fit=crop", "titulo": "Introdução à LGPD - Lei Geral de Proteção de Dados", "total_avaliacoes": 0}, {"atualizado_em": "2026-04-08T09:45:35.421032+00:00", "avaliacao_obrigatoria": false, "categoria": "Liderança", "conteudo_html": "## Seção 1: Por que Gestão do Tempo?\n\n[Imagem: https://images.unsplash.com/photo-1506784365847-bbad939e9335?w=800&auto=format&fit=crop]\n\nO tempo é o recurso mais valioso que temos - e é o único que não podemos recuperar. A **gestão do tempo** é a habilidade de organizar e planejar como dividir seu tempo entre atividades específicas.\n\n### Benefícios da Boa Gestão do Tempo\n\n• Maior produtividade\n• Menos estresse\n• Melhor qualidade de vida\n• Mais tempo para o que importa\n• Entregas mais consistentes\n• Crescimento profissional\n\n---\n\n## Seção 2: Identificando Desperdiçadores de Tempo\n\n[Imagem: https://images.unsplash.com/photo-1516321318423-f06f85e504b3?w=800&auto=format&fit=crop]\n\n### Os Principais Ladrões de Tempo\n\n**Interrupções:**\n• Notificações do celular\n• Colegas que \"só precisam de um minutinho\"\n• E-mails chegando constantemente\n• Reuniões desnecessárias\n\n**Procrastinação:**\n• Adiar tarefas difíceis\n• Perfeccionismo excessivo\n• Falta de motivação\n• Medo de falhar\n\n**Desorganização:**\n• Mesa bagunçada\n• Arquivos desorganizados\n• Falta de planejamento\n• Multitarefa excessiva\n\n---\n\n## Seção 3: Matriz de Eisenhower\n\n[Imagem: https://images.unsplash.com/photo-1484480974693-6ca0a78fb36b?w=800&auto=format&fit=crop]\n\n### Como Priorizar Tarefas\n\nA Matriz de Eisenhower divide tarefas em 4 quadrantes:\n\n| | Urgente | Não Urgente |\n|---|---|---|\n| **Importante** | FAZER AGORA | AGENDAR |\n| **Não Importante** | DELEGAR | ELIMINAR |\n\n### Exemplos Práticos\n\n**Fazer Agora (Q1):** Crises, prazos imediatos\n**Agendar (Q2):** Planejamento, desenvolvimento pessoal\n**Delegar (Q3):** Algumas reuniões, certos e-mails\n**Eliminar (Q4):** Redes sociais, conversas improdutivas\n\n---\n\n## Seção 4: Método Pomodoro\n\n[Imagem: https://images.unsplash.com/photo-1434030216411-0b793f4b4173?w=800&auto=format&fit=crop]\n\n### Como Funciona\n\nO método Pomodoro divide o trabalho em blocos de tempo:\n\n1. Escolha uma tarefa\n2. Configure o timer para **25 minutos**\n3. Trabalhe focado até o timer tocar\n4. Faça uma pausa de **5 minutos**\n5. A cada 4 pomodoros, pause **15-30 minutos**\n\n### Por que Funciona\n\n☑ Cria senso de urgência\n☑ Combate a procrastinação\n☑ Mantém o foco\n☑ Previne burnout\n☑ Mede produtividade real\n\n---\n\n## Seção 5: Planejamento Semanal e Diário\n\n[Imagem: https://images.unsplash.com/photo-1506784693919-ef06d93c28d2?w=800&auto=format&fit=crop]\n\n### Planejamento Semanal\n\nReserve 30 minutos no domingo ou segunda para:\n\n• Revisar compromissos da semana\n• Definir 3 prioridades principais\n• Bloquear tempo para tarefas importantes\n• Identificar possíveis conflitos\n\n### Planejamento Diário\n\nTodo dia, pela manhã ou na noite anterior:\n\n1. Liste todas as tarefas\n2. Priorize usando a Matriz de Eisenhower\n3. Estime tempo para cada tarefa\n4. Organize por blocos de tempo\n5. Deixe margem para imprevistos\n\n---\n\n## Seção 6: Dicas Práticas\n\n[Imagem: https://images.unsplash.com/photo-1488190211105-8b0e65b80b4e?w=800&auto=format&fit=crop]\n\n### Hábitos para Alta Produtividade\n\n☑ Comece pelas tarefas mais difíceis (Eat the Frog)\n☑ Agrupe tarefas similares\n☑ Defina horários para checar e-mails\n☑ Aprenda a dizer \"não\"\n☑ Elimine distrações no ambiente\n☑ Use ferramentas de produtividade\n☑ Durma bem e cuide da saúde\n\n### Ferramentas Úteis\n\n• Todoist, Trello, Notion (gestão de tarefas)\n• Google Calendar (agendamento)\n• Forest, Focus To-Do (Pomodoro)\n• RescueTime (análise de tempo)\n\n---\n\n## Seção 7: Conclusão\n\nA gestão do tempo é uma habilidade que se desenvolve com prática. Comece implementando uma técnica por vez e ajuste conforme necessário.\n\n**Lembre-se:** O objetivo não é estar sempre ocupado, mas sim fazer o que realmente importa de forma eficiente.\n\nParabéns por investir no seu desenvolvimento!", "criado_em": "2026-01-30T13:44:48.125863+00:00", "data_limite": null, "departamento_id": null, "descricao": "Aprenda técnicas comprovadas de gestão do tempo, priorização de tarefas, método Pomodoro e ferramentas para aumentar sua produtividade no trabalho.", "duracao_minutos": 75, "empresa_id": "012f817c-3197-4f5d-8506-4f03e12b0edd", "id": "cc074b3e-f4b1-4584-9504-afe360e08b02", "instrutor_id": null, "media_avaliacao": 0, "nivel": "iniciante", "nota_minima": 7, "obrigatorio": false, "publicado": true, "tempo_avaliacao_minutos": 0, "thumbnail_url": "https://images.unsplash.com/photo-1506784365847-bbad939e9335?w=800&auto=format&fit=crop", "titulo": "Gestão do Tempo e Produtividade", "total_avaliacoes": 0}, {"atualizado_em": "2026-04-08T09:45:35.421032+00:00", "avaliacao_obrigatoria": true, "categoria": "Liderança", "conteudo_html": "## Seção 1: Fundamentos da Liderança\n\n[Imagem: https://images.unsplash.com/photo-1522071820081-009f0129c71c?w=800&auto=format&fit=crop]\n\nA **liderança** é a capacidade de influenciar, motivar e guiar pessoas ou equipes para alcançar objetivos comuns. Diferente de ser apenas um \"chefe\", um líder inspira pelo exemplo.\n\n### Diferença entre Chefe e Líder\n\n| Chefe | Líder |\n|-------|-------|\n| Manda | Orienta |\n| Impõe medo | Gera confiança |\n| Culpa | Assume responsabilidade |\n| Diz \"eu\" | Diz \"nós\" |\n\n### Estilos de Liderança\n\n• **Autocrático** - Decisões centralizadas\n• **Democrático** - Participação da equipe\n• **Liberal** - Autonomia total\n• **Situacional** - Adapta-se ao contexto\n• **Transformacional** - Inspira mudanças\n\n---\n\n## Seção 2: Comunicação Eficaz\n\n[Imagem: https://images.unsplash.com/photo-1573164713988-8665fc963095?w=800&auto=format&fit=crop]\n\n### Escuta Ativa\n\nUm bom líder dedica tempo para ouvir sua equipe:\n\n• Mantenha contato visual\n• Não interrompa\n• Faça perguntas esclarecedoras\n• Repita para confirmar entendimento\n• Demonstre interesse genuíno\n\n### Comunicação Clara\n\n☑ Seja direto e objetivo\n☑ Adapte a linguagem ao público\n☑ Use exemplos práticos\n☑ Confirme o entendimento\n☑ Dê espaço para perguntas\n\n---\n\n## Seção 3: Motivação de Equipes\n\n[Imagem: https://images.unsplash.com/photo-1552664730-d307ca884978?w=800&auto=format&fit=crop]\n\n### Teorias da Motivação\n\n**Pirâmide de Maslow:**\n1. Necessidades fisiológicas\n2. Segurança\n3. Sociais\n4. Estima\n5. Autorrealização\n\n**Fatores Motivacionais (Herzberg):**\n• Reconhecimento\n• Crescimento profissional\n• Responsabilidade\n• Realização\n\n### Práticas para Motivar\n\n• Reconheça conquistas publicamente\n• Ofereça feedback construtivo\n• Promova desafios adequados\n• Crie ambiente de confiança\n• Invista no desenvolvimento\n\n---\n\n## Seção 4: Delegação Eficaz\n\n[Imagem: https://images.unsplash.com/photo-1600880292203-757bb62b4baf?w=800&auto=format&fit=crop]\n\n### Por que Delegar?\n\n• Desenvolve competências na equipe\n• Libera seu tempo para estratégia\n• Aumenta a produtividade geral\n• Prepara sucessores\n• Demonstra confiança\n\n### Como Delegar Corretamente\n\n1. **Escolha a pessoa certa** para a tarefa\n2. **Explique claramente** o que precisa ser feito\n3. **Defina prazos** realistas\n4. **Dê autonomia** para executar\n5. **Acompanhe** sem microgerenciar\n6. **Ofereça suporte** quando necessário\n\n---\n\n## Seção 5: Feedback Construtivo\n\n[Imagem: https://images.unsplash.com/photo-1531482615713-2afd69097998?w=800&auto=format&fit=crop]\n\n### O Modelo SBI\n\n**S - Situação:** Descreva o contexto\n**B - Comportamento:** O que a pessoa fez\n**I - Impacto:** Qual foi o resultado\n\n**Exemplo:**\n\"Na reunião de ontem (S), quando você apresentou os dados de vendas de forma visual (B), o cliente ficou mais engajado e fechamos a venda (I).\"\n\n### Dicas para Feedback\n\n☑ Seja específico\n☑ Foque no comportamento, não na pessoa\n☑ Equilibre positivo e construtivo\n☑ Faça em particular (para críticas)\n☑ Seja oportuno\n\n---\n\n## Seção 6: Gestão de Conflitos\n\n[Imagem: https://images.unsplash.com/photo-1573497019940-1c28c88b4f3e?w=800&auto=format&fit=crop]\n\n### Tipos de Conflitos\n\n• **Interpessoais** - Entre duas pessoas\n• **Intragrupais** - Dentro da equipe\n• **Intergrupais** - Entre departamentos\n\n### Estratégias de Resolução\n\n1. **Identificar** a raiz do conflito\n2. **Ouvir** todos os lados\n3. **Mediar** com imparcialidade\n4. **Buscar** soluções ganha-ganha\n5. **Documentar** acordos\n6. **Acompanhar** a implementação\n\n---\n\n## Seção 7: Desenvolvimento de Equipes\n\n[Imagem: https://images.unsplash.com/photo-1519389950473-47ba0277781c?w=800&auto=format&fit=crop]\n\n### Ciclo de Desenvolvimento (Tuckman)\n\n1. **Forming** - Formação inicial\n2. **Storming** - Conflitos e ajustes\n3. **Norming** - Estabelecimento de normas\n4. **Performing** - Alta performance\n5. **Adjourning** - Encerramento\n\n### Construindo Times de Alta Performance\n\n• Defina objetivos claros\n• Estabeleça papéis bem definidos\n• Promova confiança mútua\n• Celebre conquistas\n• Invista em capacitação contínua\n\n---\n\n## Seção 8: Conclusão\n\nLiderança é uma jornada contínua de aprendizado. Os melhores líderes:\n\n☑ Conhecem a si mesmos\n☑ Desenvolvem suas equipes\n☑ Comunicam com clareza\n☑ Inspiram pelo exemplo\n☑ Adaptam-se às mudanças\n\n**Parabéns por investir no seu desenvolvimento como líder!**", "criado_em": "2026-01-30T13:44:48.125863+00:00", "data_limite": null, "departamento_id": null, "descricao": "Desenvolva competências de liderança, aprenda a motivar equipes, delegar tarefas, dar feedback e criar um ambiente de trabalho positivo e produtivo.", "duracao_minutos": 10, "empresa_id": null, "id": "3c73f55d-2d27-41db-9883-2563f0cb638b", "instrutor_id": null, "media_avaliacao": 0, "nivel": "avancado", "nota_minima": 7, "obrigatorio": false, "publicado": true, "tempo_avaliacao_minutos": 0, "thumbnail_url": "https://images.unsplash.com/photo-1522071820081-009f0129c71c?w=800&auto=format&fit=crop", "titulo": "Liderança e Gestão de Equipes", "total_avaliacoes": 0}, {"atualizado_em": "2026-09-17T09:21:23.452777+00:00", "avaliacao_obrigatoria": false, "categoria": "Compliance", "conteudo_html": "## Seção 1: O que é Ética Profissional?\n\n[Imagem: https://images.unsplash.com/photo-1450101499163-c8848c66ca85?w=800&auto=format&fit=crop]\n\nA **ética profissional** é o conjunto de normas e valores que orientam o comportamento dos profissionais em suas atividades laborais. Vai além de simplesmente seguir regras - trata-se de fazer o que é certo.\n\n### Princípios Fundamentais\n\n• **Integridade** - Agir com honestidade em todas as situações\n• **Responsabilidade** - Assumir as consequências de suas ações\n• **Respeito** - Tratar todos com dignidade\n• **Transparência** - Ser claro e aberto nas comunicações\n• **Imparcialidade** - Não favorecer interesses pessoais\n\n---\n\n## Seção 2: Código de Conduta\n\n[Imagem: https://images.unsplash.com/photo-1589829545856-d10d557cf95f?w=800&auto=format&fit=crop]\n\n### O que é o Código de Conduta?\n\nÉ um documento que estabelece as diretrizes de comportamento esperadas de todos os colaboradores da organização.\n\n### Principais Diretrizes\n\n☑ Respeitar a diversidade e inclusão\n☑ Manter a confidencialidade das informações\n☑ Evitar conflitos de interesse\n☑ Não aceitar ou oferecer presentes indevidos\n☑ Reportar irregularidades\n☑ Proteger os ativos da empresa\n\n---\n\n## Seção 3: Conflitos de Interesse\n\n[Imagem: https://images.unsplash.com/photo-1521791136064-7986c2920216?w=800&auto=format&fit=crop]\n\n### O que é Conflito de Interesse?\n\nOcorre quando interesses pessoais podem influenciar ou parecer influenciar decisões profissionais.\n\n### Exemplos Comuns\n\n• Contratar familiares ou amigos\n• Ter participação em fornecedores\n• Aceitar presentes de clientes/fornecedores\n• Usar informações privilegiadas\n• Trabalhar para concorrentes\n\n### Como Agir?\n\n1. Identifique potenciais conflitos\n2. Declare formalmente à empresa\n3. Siga as orientações recebidas\n4. Abstenha-se de decisões conflituosas\n\n---\n\n## Seção 4: Assédio e Discriminação\n\n[Imagem: https://images.unsplash.com/photo-1573497019940-1c28c88b4f3e?w=800&auto=format&fit=crop]\n\n### Tipos de Assédio\n\n**Assédio Moral:**\n• Humilhações repetidas\n• Isolamento do colaborador\n• Sobrecarga de trabalho proposital\n• Críticas constantes e injustificadas\n\n**Assédio Sexual:**\n• Comentários ou piadas de cunho sexual\n• Toques não autorizados\n• Propostas inadequadas\n• Chantagem para favores sexuais\n\n### Como Reportar\n\n• Canal de denúncias\n• Recursos Humanos\n• Gestor imediato (se não for o assediador)\n• Ouvidoria\n\n---\n\n## Seção 5: Uso de Recursos da Empresa\n\n[Imagem: https://images.unsplash.com/photo-1496181133206-80ce9b88a853?w=800&auto=format&fit=crop]\n\n### Recursos Corporativos\n\nOs recursos da empresa devem ser usados exclusivamente para fins profissionais:\n\n• Computadores e telefones\n• E-mail corporativo\n• Impressoras e materiais\n• Veículos da empresa\n• Cartão corporativo\n\n### Boas Práticas\n\n☑ Use recursos apenas para trabalho\n☑ Cuide dos equipamentos\n☑ Não instale softwares não autorizados\n☑ Economize materiais quando possível\n☑ Devolva equipamentos ao sair da empresa\n\n---\n\n## Seção 6: Conclusão\n\n[Imagem: https://images.unsplash.com/photo-1507679799987-c73779587ccf?w=800&auto=format&fit=crop]\n\n### Lembre-se\n\nA ética profissional não é apenas sobre seguir regras - é sobre construir uma reputação de confiança e respeito.\n\n**Pergunte-se sempre:**\n\n• Estou sendo honesto?\n• Minhas ações resistiriam ao escrutínio público?\n• Estou tratando os outros como gostaria de ser tratado?\n\n**Quando em dúvida, consulte o Código de Conduta ou o RH.**\n\nParabéns por completar este treinamento sobre Ética Profissional!", "criado_em": "2026-01-30T13:44:48.125863+00:00", "data_limite": null, "departamento_id": null, "descricao": "Treinamento sobre princípios éticos, código de conduta corporativo, integridade e compliance. Essencial para todos os colaboradores da organização.", "duracao_minutos": 45, "empresa_id": null, "id": "53958301-9466-4ad2-b4ac-ff6fdf78fd86", "instrutor_id": null, "media_avaliacao": 0, "nivel": "basico", "nota_minima": 7, "obrigatorio": true, "publicado": true, "tempo_avaliacao_minutos": 0, "thumbnail_url": "https://images.unsplash.com/photo-1450101499163-c8848c66ca85?w=800&auto=format&fit=crop", "titulo": "Ética Profissional e Código de Conduta", "total_avaliacoes": 0}, {"atualizado_em": "2026-09-18T02:24:31.425847+00:00", "avaliacao_obrigatoria": true, "categoria": "Atendimento", "conteudo_html": "## Seção 1: Excelência no Atendimento\n\n[Imagem: https://images.unsplash.com/photo-1556742049-0cfed4f6a45d?w=800&auto=format&fit=crop]\n\n[Vídeo: https://www.youtube.com/watch?v=8rjey8HmRxM]\n\nO **atendimento ao cliente** é um diferencial competitivo crucial. Empresas com excelente atendimento têm clientes mais fiéis, gastam menos com aquisição e crescem de forma sustentável.\n\n### Por que Atendimento Importa?\n\n• 68% dos clientes abandonam por mau atendimento\n• Custa 5x mais conquistar novo cliente do que manter\n• Clientes satisfeitos recomendam para 9 pessoas\n• Insatisfeitos contam para 16 pessoas\n\n---\n\n## Seção 2: Perfil do Atendente Excelente\n\n[Imagem: https://images.unsplash.com/photo-1573497019940-1c28c88b4f3e?w=800&auto=format&fit=crop]\n\n### Habilidades Essenciais\n\n**Comunicação:**\n• Linguagem clara e acessível\n• Escuta ativa\n• Adaptação ao perfil do cliente\n\n**Empatia:**\n• Colocar-se no lugar do cliente\n• Entender suas necessidades\n• Demonstrar interesse genuíno\n\n**Paciência:**\n• Manter a calma em situações difíceis\n• Não levar reclamações para o lado pessoal\n• Persistir até resolver\n\n**Conhecimento:**\n• Dominar produtos/serviços\n• Conhecer processos internos\n• Manter-se atualizado\n\n---\n\n## Seção 3: Técnicas de Atendimento\n\n[Imagem: https://images.unsplash.com/photo-1552581234-26160f608093?w=800&auto=format&fit=crop]\n\n[Vídeo: https://www.youtube.com/watch?v=g3qKjo2CMY8]\n\n### Etapas do Atendimento\n\n1. **Acolhimento** - Receba com cordialidade\n2. **Identificação** - Entenda a necessidade\n3. **Solução** - Apresente alternativas\n4. **Conclusão** - Confirme a satisfação\n5. **Acompanhamento** - Faça follow-up\n\n### Frases que Encantam\n\n☑ \"Como posso ajudá-lo hoje?\"\n☑ \"Entendo sua situação...\"\n☑ \"Vou resolver isso para você\"\n☑ \"Há algo mais que eu possa fazer?\"\n☑ \"Foi um prazer atendê-lo\"\n\n### Frases a Evitar\n\n• \"Isso não é comigo\"\n• \"Não sei\"\n• \"Você está errado\"\n• \"Essa é a política da empresa\"\n• \"Você não entendeu\"\n\n---\n\n## Seção 4: Lidando com Reclamações\n\n[Imagem: https://images.unsplash.com/photo-1573497019940-1c28c88b4f3e?w=800&auto=format&fit=crop]\n\n### Método LEAD\n\n**L - Listen (Escute)** - Deixe o cliente falar\n**E - Empathize (Empatize)** - Demonstre compreensão\n**A - Apologize (Desculpe)** - Peça desculpas sinceras\n**D - Do (Aja)** - Resolva o problema\n\n### Transformando Reclamações em Oportunidades\n\n• Cada reclamação é feedback gratuito\n• Cliente que reclama quer ser ouvido\n• Resolver bem = cliente mais fiel\n• Documente para melhorias futuras\n\n---\n\n## Seção 5: Clientes Difíceis\n\n[Imagem: https://images.unsplash.com/photo-1521791136064-7986c2920216?w=800&auto=format&fit=crop]\n\n### Tipos de Clientes Difíceis\n\n**O Agressivo:**\n• Mantenha a calma\n• Não rebata agressividade\n• Foque na solução\n\n**O Indeciso:**\n• Faça perguntas direcionadas\n• Apresente opções limitadas\n• Ofereça garantias\n\n**O Detalhista:**\n• Seja preciso nas informações\n• Documente tudo\n• Tenha paciência\n\n**O Apressado:**\n• Seja objetivo\n• Vá direto ao ponto\n• Priorize o atendimento\n\n---\n\n## Seção 6: Atendimento Multicanal\n\n[Imagem: https://images.unsplash.com/photo-1551434678-e076c223a692?w=800&auto=format&fit=crop]\n\n### Canais de Atendimento\n\n• **Presencial** - Expressão facial e corporal\n• **Telefone** - Tom de voz é fundamental\n• **E-mail** - Resposta estruturada e formal\n• **Chat** - Agilidade e clareza\n• **Redes Sociais** - Transparência e rapidez\n\n### Princípio da Consistência\n\nIndependente do canal, o cliente deve receber:\n☑ Mesma qualidade de atendimento\n☑ Informações consistentes\n☑ Solução do problema\n☑ Tratamento respeitoso\n\n---\n\n## Seção 7: Conclusão\n\n[Imagem: https://images.unsplash.com/photo-1552664730-d307ca884978?w=800&auto=format&fit=crop]\n\n### Resumo das Boas Práticas\n\n☑ Trate cada cliente como único\n☑ Pratique escuta ativa\n☑ Resolva problemas com empatia\n☑ Vá além das expectativas\n☑ Peça feedback\n☑ Melhore continuamente\n\n**\"O cliente não é uma interrupção do nosso trabalho. Ele é a razão do nosso trabalho.\"**\n\nParabéns por completar este treinamento!", "criado_em": "2026-01-30T13:44:48.125863+00:00", "data_limite": null, "departamento_id": null, "descricao": "Treinamento completo sobre técnicas de atendimento, resolução de conflitos, empatia e como criar experiências memoráveis para os clientes.", "duracao_minutos": 120, "empresa_id": null, "id": "ffa9130d-5522-436c-a14d-ec66ec4f797d", "instrutor_id": null, "media_avaliacao": 0, "nivel": "intermediario", "nota_minima": 7, "obrigatorio": false, "publicado": false, "tempo_avaliacao_minutos": 20, "thumbnail_url": null, "titulo": "Atendimento ao Cliente de Excelência", "total_avaliacoes": 0}, {"atualizado_em": "2026-09-17T09:21:23.452777+00:00", "avaliacao_obrigatoria": true, "categoria": "Tributário", "conteudo_html": "## Seção 1: O que é a Reforma Tributária\n\nA **Reforma Tributária** é a maior reformulação do sistema de tributação sobre o consumo no Brasil desde a Constituição de 1988. Ela foi aprovada por meio da **Emenda Constitucional nº 132/2023** e regulamentada pela **Lei Complementar nº 214/2025**, que detalha como os novos tributos vão funcionar na prática.\n\nO objetivo central da reforma é **simplificar** o sistema tributário brasileiro, que hoje é considerado um dos mais complexos do mundo, unificando cinco tributos diferentes em apenas três novos tributos sobre o consumo.\n\nEste treinamento foi criado como **modelo padrão**, disponível para todos os departamentos e empresas, para que todos os colaboradores entendam os principais conceitos da reforma, o cronograma de transição e os impactos no dia a dia do trabalho.\n\n[Imagem: https://images.unsplash.com/photo-1554224155-6726b3ff858f?w=800&auto=format&fit=crop]\n\n**Ao final deste treinamento você será capaz de:**\n☑ Explicar o que é a Reforma Tributária e por que ela foi criada\n☑ Diferenciar os três novos tributos: IBS, CBS e Imposto Seletivo\n☑ Entender o cronograma de transição entre 2026 e 2033\n☑ Identificar os principais impactos para empresas e consumidores\n☑ Responder com segurança à avaliação final\n\n---\n\n## Seção 2: Por que a Reforma foi necessária\n\nAntes da reforma, o consumo de bens e serviços no Brasil era tributado por **cinco tributos diferentes**, cada um com sua própria legislação, alíquotas e obrigações acessórias:\n\n| Tributo | Competência | O que tributava |\n|---|---|---|\n| PIS | Federal | Faturamento/receita |\n| Cofins | Federal | Faturamento/receita |\n| IPI | Federal | Produtos industrializados |\n| ICMS | Estadual | Circulação de mercadorias e alguns serviços |\n| ISS | Municipal | Prestação de serviços |\n\nEssa multiplicidade de regras gerava diversos problemas:\n\n1. **Complexidade excessiva**: empresas precisavam lidar com milhares de regras estaduais e municipais diferentes.\n2. **Insegurança jurídica**: interpretações divergentes sobre o que era \"mercadoria\" e o que era \"serviço\" geravam disputas judiciais constantes.\n3. **Cumulatividade parcial**: nem sempre era possível aproveitar integralmente os créditos dos tributos pagos nas etapas anteriores da cadeia produtiva.\n4. **Guerra fiscal**: estados e municípios concediam benefícios fiscais para atrair empresas, distorcendo a concorrência.\n5. **Custo de conformidade elevado**: o Brasil é reconhecido internacionalmente pelo alto número de horas gastas por empresas apenas para calcular e pagar tributos.\n\n[Vídeo: https://www.youtube.com/watch?v=GCwls70yde4]\n\n---\n\n## Seção 3: O novo modelo — IVA Dual (IBS e CBS)\n\nA reforma substitui PIS, Cofins, ICMS e ISS por um modelo de **IVA Dual** (Imposto sobre Valor Agregado), composto por dois tributos que incidem sobre a mesma base, mas com competências diferentes:\n\n### IBS — Imposto sobre Bens e Serviços\n- Competência **compartilhada** entre Estados, Distrito Federal e Municípios.\n- Substitui o **ICMS** (estadual) e o **ISS** (municipal).\n- Administrado por um novo órgão: o **Comitê Gestor do IBS**.\n\n### CBS — Contribuição sobre Bens e Serviços\n- Competência **federal** (União).\n- Substitui o **PIS** e a **Cofins**.\n- Administrada pela Receita Federal do Brasil.\n\nApesar de terem administrações diferentes, IBS e CBS seguem **a mesma legislação, os mesmos fatos geradores e as mesmas regras de apuração**, o que simplifica bastante o cumprimento das obrigações por parte das empresas — é como se, na prática, existisse um único imposto sobre o consumo, apenas \"dividido\" entre União, Estados e Municípios.\n\n[Imagem: https://images.unsplash.com/photo-1521737604893-d14cc237f11d?w=800&auto=format&fit=crop]\n\n**Importante:** o IPI (Imposto sobre Produtos Industrializados) não é extinto formalmente, mas tem sua alíquota **reduzida a zero** para a maioria dos produtos a partir de 2027 — exceto para itens fabricados na Zona Franca de Manaus, que mantêm o IPI como mecanismo de incentivo regional.\n\n---\n\n## Seção 4: Imposto Seletivo (IS) — o \"imposto do pecado\"\n\nAlém do IBS e da CBS, a reforma cria o **Imposto Seletivo (IS)**, um tributo federal com finalidade **extrafiscal**: seu objetivo não é arrecadar, mas sim **desestimular o consumo** de produtos e serviços prejudiciais à saúde ou ao meio ambiente.\n\nPor isso, o IS ficou popularmente conhecido como **\"imposto do pecado\"**.\n\n**Exemplos de produtos sujeitos ao Imposto Seletivo:**\n• Cigarros e demais derivados de tabaco\n• Bebidas alcoólicas\n• Bebidas açucaradas\n• Veículos, embarcações e aeronaves poluentes\n• Bens e atividades extrativos minerais\n\n**Características importantes do Imposto Seletivo:**\n☑ Não busca neutralidade econômica — ao contrário do IBS e da CBS\n☑ Incide uma única vez sobre o produto (não é plurifásico como o IBS/CBS)\n☑ **Não gera direito a crédito** nas etapas seguintes da cadeia produtiva\n☑ Pode incidir sobre extração, produção, comercialização ou importação\n\n[Vídeo: https://www.youtube.com/watch?v=9nsHyjJP3gM]\n\n---\n\n## Seção 5: Princípios fundamentais da Reforma\n\nToda a lógica do novo sistema tributário se apoia em alguns princípios centrais que representam uma mudança profunda em relação ao modelo anterior:\n\n### Não cumulatividade plena\nNo modelo antigo, empresas nem sempre conseguiam aproveitar 100% dos créditos tributários pagos na etapa anterior da cadeia. No novo modelo, **praticamente todo tributo pago vira crédito** a ser compensado na etapa seguinte, evitando o chamado \"efeito cascata\".\n\n### Tributação no destino\nHoje, parte da arrecadação fica no local de **produção** da mercadoria. Com a reforma, o imposto passa a ser recolhido no local de **consumo** (destino), o que tende a reduzir a guerra fiscal entre estados, já que não haverá mais vantagem tributária em produzir em um determinado estado apenas por causa de benefícios fiscais.\n\n### Transparência\nO valor do imposto pago deve ser informado de forma clara ao consumidor, por exemplo no cupom fiscal (\"imposto por fora\"), permitindo que as pessoas saibam exatamente quanto estão pagando de tributos em cada compra.\n\n### Simplicidade\nUma legislação única (a LC 214/2025) substitui milhares de normas estaduais e municipais diferentes, reduzindo a complexidade e o custo de conformidade das empresas.\n\n[Imagem: https://images.unsplash.com/photo-1553877522-43269d4ea984?w=800&auto=format&fit=crop]\n\n---\n\n## Seção 6: Cronograma de transição (2026–2033)\n\nA transição para o novo sistema é **gradual**, para dar tempo de adaptação a empresas, governos e sistemas de tecnologia. O cronograma oficial é o seguinte:\n\n| Período | O que acontece |\n|---|---|\n| 2026 | Fase de testes: cobrança simbólica de CBS (0,9%) e IBS (0,1%), somando 1%, sem aumento da carga tributária — os valores pagos são compensados com PIS/Cofins |\n| 2027 | Extinção do PIS e da Cofins; CBS passa a valer plenamente; IPI é reduzido a zero (exceto Zona Franca de Manaus); início da cobrança do Imposto Seletivo |\n| 2029 a 2032 | Transição gradual do ICMS e do ISS para o IBS, com redução progressiva das alíquotas dos tributos antigos e aumento progressivo do IBS |\n| 2033 | Extinção definitiva do ICMS e do ISS; novo sistema (IBS + CBS + IS) passa a vigorar de forma completa e plena |\n\n**Por que uma transição tão longa?** Porque o novo modelo muda completamente a lógica de arrecadação (do local de produção para o local de consumo), o que impacta diretamente a receita de estados e municípios. Um período de transição de quase 10 anos permite ajustes graduais, evitando perdas bruscas de arrecadação para os entes federativos.\n\n[Vídeo: https://www.youtube.com/watch?v=sanN2NE7oys]\n\n---\n\n## Seção 7: Regimes diferenciados e proteção social\n\nA reforma prevê mecanismos específicos para proteger setores essenciais e famílias de baixa renda:\n\n### Cesta básica nacional\nUma lista de alimentos considerados essenciais passa a ter **alíquota zero** de IBS e CBS, reduzindo o impacto da reforma no custo de vida da população.\n\n### Regimes de alíquota reduzida\nSetores como saúde, educação, transporte público coletivo, produtos agropecuários e atividades culturais têm **redução de 60% na alíquota padrão**, por serem considerados socialmente relevantes.\n\n### Cashback (devolução de tributos)\nFamílias de baixa renda, inscritas em programas sociais, têm direito à **devolução de parte do IBS e da CBS** pagos em determinadas compras (como energia elétrica, água, gás de cozinha e telefonia), tornando o sistema mais justo socialmente.\n\n### Simples Nacional\nEmpresas optantes pelo Simples Nacional **não são obrigadas a migrar** para o novo regime de apuração do IBS/CBS. Elas podem continuar recolhendo os tributos de forma unificada, como já fazem hoje, embora também possam optar por apurar o IBS/CBS \"por fora\" em situações específicas, quando for vantajoso para o negócio.\n\n[Imagem: https://images.unsplash.com/photo-1521737604893-d14cc237f11d?w=800&auto=format&fit=crop]\n\n---\n\n## Seção 8: Split Payment e Comitê Gestor do IBS\n\n### Split Payment\nUm dos grandes avanços tecnológicos da reforma é o **split payment**: no momento em que o pagamento de uma compra é processado (por cartão, Pix, boleto etc.), o valor do imposto já é **automaticamente separado e recolhido** diretamente para o Fisco, sem passar pelo caixa da empresa.\n\nEsse mecanismo tem como objetivo **reduzir a sonegação fiscal** e simplificar a fiscalização, já que o imposto deixa de \"passar\" pela contabilidade da empresa antes de ser recolhido.\n\n### Comitê Gestor do IBS\nComo o IBS é de competência compartilhada entre os mais de 5.000 municípios e os 26 estados + Distrito Federal, foi criado o **Comitê Gestor do IBS**, um órgão responsável por:\n\n• Arrecadar, compensar e distribuir a receita do IBS entre os entes federativos\n• Editar normas e regulamentos uniformes para todo o território nacional\n• Uniformizar a interpretação da legislação, evitando disputas entre estados e municípios\n• Atuar no contencioso administrativo relacionado ao IBS\n\n[Imagem: https://images.unsplash.com/photo-1451187580459-43490279c0fa?w=800&auto=format&fit=crop]\n\n---\n\n## Seção 9: Impactos práticos para as empresas\n\nA Reforma Tributária exige que as empresas se preparem em diversas frentes:\n\n1. **Sistemas e ERPs**: atualização dos sistemas de emissão de notas fiscais e apuração de tributos para lidar com IBS, CBS e IS simultaneamente com os tributos antigos, durante o período de transição.\n2. **Precificação**: revisão da formação de preços, já que a forma de calcular e repassar tributos muda significativamente.\n3. **Capacitação de equipes**: áreas fiscal, contábil, financeira e comercial precisam entender o novo modelo para atuar corretamente durante a transição.\n4. **Contratos**: cláusulas contratuais que mencionam tributos específicos (como ICMS ou ISS) podem precisar de revisão jurídica.\n5. **Fluxo de caixa**: o split payment pode alterar o fluxo de caixa das empresas, já que o valor do imposto é recolhido no momento do pagamento, e não mais posteriormente.\n\n**Por que isso importa para você, mesmo fora da área fiscal?** Porque a reforma afeta preços, contratos, sistemas e processos em praticamente todas as áreas da empresa — vendas, compras, TI, jurídico e operações. Entender o básico da reforma ajuda todo colaborador a compreender mudanças que vão aparecer no dia a dia, como alterações em notas fiscais, preços de produtos e sistemas internos.\n\n[Imagem: https://images.unsplash.com/photo-1450101499163-c8848c66ca85?w=800&auto=format&fit=crop]\n\n---\n\n## Seção 10: Conclusão\n\nA Reforma Tributária representa a mudança mais profunda no sistema de tributação sobre o consumo desde a Constituição de 1988. Em resumo:\n\n☑ Cinco tributos (PIS, Cofins, IPI, ICMS e ISS) dão lugar a três novos tributos (IBS, CBS e Imposto Seletivo)\n☑ O modelo segue os princípios da não cumulatividade plena e da tributação no destino\n☑ A transição ocorre de forma gradual, entre 2026 e 2033\n☑ Existem mecanismos de proteção social, como cesta básica com alíquota zero e cashback\n☑ Empresas precisam se preparar em sistemas, precificação, contratos e capacitação de equipes\n\nEste treinamento é apenas o ponto de partida. À medida que a regulamentação avança e novas normas são publicadas pelo Comitê Gestor do IBS e pela Receita Federal, este conteúdo poderá ser atualizado — fique atento a comunicados internos sobre o tema.\n\nAo concluir a leitura, avance para a **avaliação final**, com 22 perguntas, para validar seu aprendizado e liberar seu certificado.", "criado_em": "2026-08-30T11:46:21.295612+00:00", "data_limite": null, "departamento_id": null, "descricao": "Treinamento modelo sobre a Reforma Tributária brasileira (EC 132/2023 e LC 214/2025): o que muda, os novos tributos IBS, CBS e Imposto Seletivo, o cronograma de transição até 2033 e os impactos práticos para empresas e colaboradores.", "duracao_minutos": 90, "empresa_id": null, "id": "3fcacb8b-8d03-43d9-a0c8-0f3d3d1ca548", "instrutor_id": null, "media_avaliacao": 0, "nivel": "basico", "nota_minima": 7, "obrigatorio": false, "publicado": true, "tempo_avaliacao_minutos": 45, "thumbnail_url": "https://images.unsplash.com/photo-1554224155-6726b3ff858f?w=1200&auto=format&fit=crop", "titulo": "Reforma Tributária: Guia Completo (IBS, CBS e Imposto Seletivo)", "total_avaliacoes": 0}, {"atualizado_em": "2026-09-17T09:21:23.452777+00:00", "avaliacao_obrigatoria": false, "categoria": "Recursos Humanos", "conteudo_html": "## Seção 1: Bem-vindo à Empresa!\n\nSeja muito bem-vindo(a) à nossa equipe! Este treinamento irá ajudá-lo a conhecer nossa cultura, valores e tudo que você precisa saber para ter sucesso aqui.\n\n[Imagem: https://images.unsplash.com/photo-1522071820081-009f0129c71c?w=800]\n\n### Nossa Missão:\nTransformar vidas através de soluções inovadoras que fazem a diferença no dia a dia das pessoas.\n\n### Nossos Valores:\n• **Integridade** - Agimos com ética e transparência\n• **Inovação** - Buscamos sempre melhorar\n• **Colaboração** - Trabalhamos juntos\n• **Excelência** - Entregamos qualidade\n\n---\n\n## Seção 2: Estrutura Organizacional\n\n[Vídeo: https://www.youtube.com/watch?v=1Rb0fH3O3pw]\n\nConheça como nossa empresa está organizada:\n\n1. **Diretoria Executiva** - Define a estratégia\n2. **Gerências** - Gerenciam áreas específicas\n3. **Coordenações** - Coordenam equipes\n4. **Equipes Operacionais** - Executam as atividades\n\n[Imagem: https://images.unsplash.com/photo-1552664730-d307ca884978?w=800]\n\n---\n\n## Seção 3: Políticas e Benefícios\n\n### Horário de Trabalho:\n• Entrada: 8h às 9h (flexível)\n• Saída: 17h às 18h\n• Intervalo: 1h para almoço\n\n### Benefícios:\n\n☑ Vale-refeição/alimentação\n☑ Plano de saúde e odontológico\n☑ Seguro de vida\n☑ Participação nos lucros\n☑ Auxílio home office\n☑ Day off no aniversário\n☑ Gympass\n\n[Imagem: https://images.unsplash.com/photo-1521791136064-7986c2920216?w=800]\n\n---\n\n## Seção 4: Próximos Passos\n\n### Sua primeira semana:\n\n1. **Dia 1** - Configuração de acessos e equipamentos\n2. **Dia 2** - Conhecer a equipe e o gestor\n3. **Dia 3** - Treinamentos específicos da área\n4. **Dia 4** - Acompanhamento de processos\n5. **Dia 5** - Reunião de feedback inicial\n\n### Canais de Comunicação:\n\n• **E-mail corporativo** - Comunicação formal\n• **Teams** - Comunicação do dia a dia\n• **Intranet** - Notícias e documentos\n• **RH** - Dúvidas sobre benefícios e folha", "criado_em": "2026-09-17T09:21:23.452777+00:00", "data_limite": null, "departamento_id": null, "descricao": "Programa de onboarding completo para novos funcionários conhecerem a cultura, valores e processos da empresa.", "duracao_minutos": 90, "empresa_id": null, "id": "ae6852e3-de9d-4f96-ade5-4a8f645928f5", "instrutor_id": null, "media_avaliacao": 0, "nivel": "basico", "nota_minima": 7, "obrigatorio": false, "publicado": true, "tempo_avaliacao_minutos": 0, "thumbnail_url": "https://images.unsplash.com/photo-1522071820081-009f0129c71c?w=1200&auto=format&fit=crop", "titulo": "Integração de Novos Colaboradores", "total_avaliacoes": 0}, {"atualizado_em": "2026-09-17T10:18:36.914904+00:00", "avaliacao_obrigatoria": true, "categoria": "Tributário", "conteudo_html": "## Seção 1: Recapitulando e Conectando com a Prática\n\nSe você já concluiu o **Módulo 1 (Fundamentos)**, sabe que a partir de 2026 o Brasil passa a conviver, de forma gradual, com o IBS, a CBS e o Imposto Seletivo. Mas o que isso significa **na prática do dia a dia** de uma empresa?\n\nNeste módulo, vamos sair da teoria e entrar nos números: como precificar um produto no novo modelo, como revisar contratos, como preparar os sistemas e quais são os impactos específicos para quem trabalha no comércio, na indústria ou em serviços.\n\n[Imagem: https://images.unsplash.com/photo-1454165804606-c3d57bc86b40?w=800&auto=format&fit=crop]\n\n**Pré-requisito:** recomendamos concluir o Módulo 1 antes deste, pois aqui não repetiremos os conceitos básicos de IBS, CBS e Imposto Seletivo.\n\n---\n\n## Seção 2: Impactos na Precificação\n\nHoje, boa parte dos tributos (como o ICMS) está **embutida no preço** e nem sempre é claramente visível ao consumidor. Com a reforma, o valor do imposto passa a ser destacado \"por fora\", de forma transparente.\n\n### Exemplo prático simplificado\n\nImagine um produto vendido hoje por **R$ 100,00**, já com tributos embutidos. Na transição para o novo modelo, a empresa precisa recalcular:\n\n| Etapa | O que muda |\n|---|---|\n| Antes | ICMS, PIS e Cofins embutidos e calculados por dentro |\n| Depois | IBS + CBS destacados \"por fora\", com alíquota informada ao cliente |\n| Resultado | O preço final pode até se manter, mas a composição do preço muda completamente |\n\n**Atenção:** a reforma não define, por si só, se os preços vão subir ou descer — isso depende da alíquota final de cada setor e das reduções específicas (como a da cesta básica, vista no Módulo 1). O importante é que a empresa **recalcule sua margem** considerando a nova estrutura, e não apenas substitua o tributo antigo pelo novo \"no mesmo valor\".\n\n[Imagem: https://images.unsplash.com/photo-1554224155-8d04cb21cd6c?w=800&auto=format&fit=crop]\n\n---\n\n## Seção 3: Revisão de Contratos e Sistemas\n\n### Contratos\n\nMuitos contratos comerciais mencionam explicitamente tributos que deixarão de existir, como **ICMS** e **ISS**. Cláusulas de reajuste, repasse de tributos e formação de preço precisam ser revisadas juridicamente para:\n\n• Substituir referências a tributos extintos pelos novos (IBS/CBS)\n• Ajustar fórmulas de reajuste de preço que citem alíquotas antigas\n• Rever cláusulas de responsabilidade tributária entre as partes\n\n### Sistemas e ERPs\n\nDurante o período de transição (2026-2033), os sistemas de emissão de nota fiscal e apuração de tributos vão precisar **calcular tributos antigos e novos ao mesmo tempo**. Isso exige:\n\n☑ Atualização do ERP e do sistema de emissão de notas fiscais\n☑ Testes de emissão com os novos campos de IBS/CBS\n☑ Treinamento das equipes fiscal e financeira\n☑ Acompanhamento das notas técnicas publicadas pelo Comitê Gestor do IBS\n\n[Imagem: https://images.unsplash.com/photo-1551288049-bebda4e38f71?w=800&auto=format&fit=crop]\n\n---\n\n## Seção 4: O Simples Nacional na Reforma\n\nEmpresas do **Simples Nacional** têm um tratamento especial: elas **não são obrigadas** a migrar para o regime normal de apuração do IBS/CBS e podem continuar recolhendo tributos de forma unificada, como hoje.\n\nPorém, existe um detalhe importante:\n\n• Uma empresa do Simples que vende para outra empresa (fora do Simples) pode gerar **menos crédito tributário** para quem compra, porque o Simples recolhe de forma simplificada.\n• Isso pode, na prática, tornar fornecedores do Simples **menos competitivos** em vendas B2B (para outras empresas), mesmo mantendo seus preços.\n• Por isso, empresas do Simples Nacional também podem optar, em situações específicas, por apurar o IBS/CBS \"por fora\" — se isso for vantajoso para manter clientes empresariais.\n\n[Vídeo: https://www.youtube.com/watch?v=Wp02_w4Rb9U]\n\n---\n\n## Seção 5: Impactos por Setor\n\n### Comércio e Varejo\n\nO varejo lida diretamente com o consumidor final e sentirá rapidamente qualquer mudança na composição do preço. Pontos de atenção: gestão de estoque na transição (produtos \"antigos\" x \"novos\" tributos), atualização de PDVs (pontos de venda) e comunicação clara ao cliente sobre o novo modelo.\n\n### Indústria\n\nA indústria tende a se beneficiar da não cumulatividade plena, já que hoje enfrenta mais dificuldade para aproveitar créditos em toda a cadeia produtiva. Pontos de atenção: revisão de custos de insumos e formação de preço de venda para distribuidores.\n\n### Serviços\n\nO setor de serviços é hoje o maior empregador formal do país e, historicamente, tinha uma carga tributária proporcionalmente menor em alguns municípios (via ISS). A adaptação ao novo modelo tende a exigir atenção redobrada em precificação, já que a alíquota padrão do IBS+CBS pode ser diferente da alíquota de ISS praticada antes.\n\n[Vídeo: https://www.youtube.com/watch?v=LS2mgKXsK34]\n\n---\n\n## Seção 6: Conclusão e Próximos Passos\n\nNeste módulo você viu como a Reforma Tributária se traduz em ações concretas: revisão de preços, contratos, sistemas e uma análise específica por setor.\n\n☑ Entenda como recalcular a precificação considerando o imposto \"por fora\"\n☑ Saiba quais cláusulas contratuais merecem revisão jurídica\n☑ Conheça os cuidados na atualização de sistemas e ERPs\n☑ Entenda as particularidades do Simples Nacional na reforma\n☑ Identifique os principais pontos de atenção do seu setor\n\nNo **Módulo 3**, vamos aprofundar dois temas técnicos essenciais para quem trabalha com fiscal e contabilidade: os **créditos tributários na prática** (com cálculo) e o funcionamento **passo a passo do split payment**.\n\nAo concluir a leitura, avance para a avaliação final deste módulo.", "criado_em": "2026-09-17T10:18:36.914904+00:00", "data_limite": null, "departamento_id": null, "descricao": "Continuação do Módulo 1 (Fundamentos). Mostra, na prática, como a Reforma Tributária impacta precificação, contratos, sistemas e o dia a dia de empresas de diferentes setores — com exemplos numéricos e estudos de caso.", "duracao_minutos": 75, "empresa_id": null, "id": "f00ec5df-0fed-47a9-b069-42ad51b0af9a", "instrutor_id": null, "media_avaliacao": 0, "nivel": "intermediario", "nota_minima": 7, "obrigatorio": false, "publicado": true, "tempo_avaliacao_minutos": 30, "thumbnail_url": "https://images.unsplash.com/photo-1454165804606-c3d57bc86b40?w=1200&auto=format&fit=crop", "titulo": "Reforma Tributária - Módulo 2: Aplicação Prática nas Empresas", "total_avaliacoes": 0}, {"atualizado_em": "2026-09-17T10:19:33.190172+00:00", "avaliacao_obrigatoria": true, "categoria": "Tributário", "conteudo_html": "## Seção 1: Recapitulando os Módulos Anteriores\n\nNos módulos 1 e 2 você aprendeu os conceitos fundamentais da Reforma Tributária (IBS, CBS, Imposto Seletivo) e como ela impacta a precificação, os contratos e os sistemas das empresas.\n\nNeste módulo avançado, o foco é técnico: como calcular créditos tributários na prática, como funciona o split payment por dentro, e o que muda na contabilidade e na escrituração fiscal durante a transição.\n\n[Imagem: https://images.unsplash.com/photo-1554224155-6726b3ff858f?w=800&auto=format&fit=crop]\n\n**Público recomendado:** profissionais de contabilidade, fiscal, financeiro e áreas correlatas.\n\n---\n\n## Seção 2: Não Cumulatividade Plena na Prática\n\nNo modelo antigo, nem todo tributo pago numa etapa da cadeia virava crédito na etapa seguinte — havia muitas restrições (por exemplo, discussões sobre o que é \"insumo\" para fins de crédito de PIS/Cofins). No novo modelo, a regra é simples: **se a compra tem relação com a atividade econômica da empresa, ela gera crédito.**\n\n### Exemplo prático de cálculo simplificado\n\nImagine uma indústria que compra insumos por **R$ 1.000,00**, pagando IBS+CBS de 20% (alíquota ilustrativa, apenas para o exemplo): ela paga **R$ 200,00** de tributo na compra.\n\nAo vender o produto final por **R$ 3.000,00**, também com alíquota de 20%, ela deveria recolher **R$ 600,00**. Mas como já pagou R$ 200,00 na compra dos insumos, ela **credita esse valor** e recolhe apenas a diferença:\n\n| Etapa | Valor | Tributo (20%) | Crédito | A recolher |\n|---|---|---|---|---|\n| Compra de insumos | R$ 1.000,00 | R$ 200,00 | — | — |\n| Venda do produto | R$ 3.000,00 | R$ 600,00 | R$ 200,00 | R$ 400,00 |\n\nIsso evita o **efeito cascata**, em que o tributo incide sobre tributo em cada etapa da cadeia produtiva.\n\n[Imagem: https://images.unsplash.com/photo-1551288049-bebda4e38f71?w=800&auto=format&fit=crop]\n\n---\n\n## Seção 3: O que Pode e o que Não Pode Gerar Crédito\n\n### Em regra, geram crédito:\n\n☑ Insumos diretos de produção\n☑ Serviços de apoio à atividade econômica (contabilidade, limpeza, manutenção)\n☑ Bens do ativo imobilizado usados na atividade da empresa\n☑ Energia elétrica e comunicação usadas na operação\n\n### Atenção especial:\n\n• **Imposto Seletivo NÃO gera crédito** nas etapas seguintes da cadeia (diferente do IBS e da CBS) — ele é um tributo monofásico, cobrado uma única vez.\n• Compras para uso pessoal dos sócios ou não relacionadas à atividade da empresa **não geram crédito**.\n• O saldo de crédito acumulado pode ser objeto de **ressarcimento** em prazos definidos pela legislação, o que é uma mudança importante em relação ao modelo antigo (onde créditos acumulados de ICMS, por exemplo, muitas vezes ficavam \"presos\").\n\n[Imagem: https://images.unsplash.com/photo-1554224155-8d04cb21cd6c?w=800&auto=format&fit=crop]\n\n---\n\n## Seção 4: Split Payment — Passo a Passo Técnico\n\nO **split payment** é um dos mecanismos mais inovadores da reforma. Veja o fluxo simplificado de uma compra com cartão, Pix ou boleto:\n\n1. **Cliente paga** a compra (R$ 1.000,00, por exemplo) através de um meio de pagamento eletrônico.\n2. **A instituição financeira ou arranjo de pagamento** (banco, adquirente, Pix) identifica automaticamente qual parcela do valor corresponde ao IBS e à CBS da operação.\n3. **O valor do tributo é separado no momento da transação** e recolhido diretamente para o Fisco (Comitê Gestor do IBS e Receita Federal).\n4. **O valor líquido** (já sem o tributo) é depositado na conta da empresa vendedora.\n\n[Vídeo: https://www.youtube.com/watch?v=27SgkainM3Y]\n\n### Por que isso importa para a contabilidade?\n\n• O fluxo de caixa da empresa muda: o dinheiro que \"entrava\" e depois era usado para pagar tributos, agora **nunca chega a entrar** — o tributo já sai automaticamente.\n• Isso exige um **replanejamento do fluxo de caixa**, já que a empresa não terá mais o tributo \"disponível\" temporariamente até a data de pagamento.\n• Reduz drasticamente o risco de sonegação, mas também reduz a margem de manobra financeira que algumas empresas tinham ao usar o valor do tributo como capital de giro temporário — um hábito que se torna ainda mais arriscado com a reforma.\n\n[Vídeo: https://www.youtube.com/watch?v=Dk98Pr3NyTU]\n\n---\n\n## Seção 5: Impactos na Contabilidade e Escrituração Fiscal\n\n### O que muda na escrituração\n\n• Novos campos na EFD (Escrituração Fiscal Digital) para registrar IBS, CBS e Imposto Seletivo separadamente\n• Necessidade de conciliar, durante a transição, tributos antigos (ICMS, ISS, PIS, Cofins) e novos (IBS, CBS) na mesma escrituração\n• Revisão do plano de contas contábil para refletir corretamente os novos tributos e seus créditos\n\n### Checklist para o setor contábil/fiscal\n\n☑ Mapear todos os produtos/serviços e suas alíquotas no novo modelo\n☑ Atualizar o plano de contas e os relatórios gerenciais\n☑ Treinar a equipe nas novas obrigações acessórias\n☑ Revisar o fluxo de caixa considerando o split payment\n☑ Acompanhar publicações do Comitê Gestor do IBS e da Receita Federal\n☑ Realizar simulações e conferências durante a fase de testes (2026)\n\n[Imagem: https://images.unsplash.com/photo-1554224173-8b9de5a8d6b3?w=800&auto=format&fit=crop]\n\n---\n\n## Seção 6: Conclusão\n\nVocê concluiu o módulo mais técnico da série. Recapitulando:\n\n☑ A não cumulatividade plena permite creditar praticamente todo tributo pago na cadeia\n☑ O Imposto Seletivo é exceção: não gera crédito\n☑ O split payment recolhe o tributo automaticamente no momento do pagamento\n☑ A contabilidade e a escrituração fiscal precisam se adaptar aos novos campos e ao novo fluxo de caixa\n\nNo **Módulo 4**, o último da série, vamos abordar compliance, fiscalização e cenários específicos por setor — encerrando com uma visão completa da Reforma Tributária.\n\nAo concluir a leitura, avance para a avaliação final deste módulo.", "criado_em": "2026-09-17T10:19:33.190172+00:00", "data_limite": null, "departamento_id": null, "descricao": "Continuação do Módulo 2. Aprofunda, com exemplos numéricos, como funciona a não cumulatividade plena na prática, o passo a passo técnico do split payment e os principais impactos na contabilidade e na escrituração fiscal.", "duracao_minutos": 80, "empresa_id": null, "id": "fdc23e97-02a1-4b5e-a20c-7ada60b8beb7", "instrutor_id": null, "media_avaliacao": 0, "nivel": "avancado", "nota_minima": 7, "obrigatorio": false, "publicado": true, "tempo_avaliacao_minutos": 35, "thumbnail_url": "https://images.unsplash.com/photo-1554224155-6726b3ff858f?w=1200&auto=format&fit=crop", "titulo": "Reforma Tributária - Módulo 3: Créditos Tributários, Split Payment e Transição Contábil", "total_avaliacoes": 0}, {"atualizado_em": "2026-09-17T10:21:24.149025+00:00", "avaliacao_obrigatoria": true, "categoria": "Tributário", "conteudo_html": "## Seção 1: Recapitulando a Jornada\n\nVocê chegou ao módulo final da série sobre a Reforma Tributária. Nos módulos anteriores, você aprendeu os fundamentos (Módulo 1), a aplicação prática nas empresas (Módulo 2) e os detalhes técnicos de créditos e split payment (Módulo 3).\n\nNeste módulo, o foco é **compliance e fiscalização**: como o novo sistema será fiscalizado, o que é o Programa Nacional de Conformidade Tributária e como diferentes setores devem se preparar para os próximos anos.\n\n[Imagem: https://images.unsplash.com/photo-1521737604893-d14cc237f11d?w=800&auto=format&fit=crop]\n\n---\n\n## Seção 2: O Papel do Comitê Gestor do IBS na Fiscalização\n\nComo vimos no Módulo 1, o **Comitê Gestor do IBS** é o órgão responsável por administrar o IBS de forma compartilhada entre os mais de 5.000 municípios e os 26 estados + Distrito Federal.\n\nNo campo da fiscalização, o Comitê Gestor tem funções específicas:\n\n• Definir regras **uniformes** de fiscalização para todo o território nacional, evitando que cada estado ou município fiscalize de forma diferente\n• Coordenar a **atuação conjunta** com a Receita Federal (que fiscaliza a CBS)\n• Administrar o **contencioso administrativo** relacionado ao IBS, ou seja, os processos em que empresas contestam autuações\n• Operar **câmaras temáticas**, dedicadas a áreas como tecnologia, arrecadação, fiscalização e litígios\n\n### Por que a uniformização importa?\n\nNo modelo antigo, uma empresa que atuava em vários estados precisava entender **27 legislações diferentes de ICMS**. Com o IBS, a legislação e as regras de fiscalização são as mesmas em todo o país — o que barateia o custo de conformidade, mas também significa que erros passam a ser identificados de forma mais padronizada e sistemática.\n\n[Vídeo: https://www.youtube.com/watch?v=jKSO0ZcWWJI]\n\n---\n\n## Seção 3: Programa Nacional de Conformidade Tributária\n\nPara ajudar empresas na fase de testes (2026) e na transição, a Receita Federal e o Comitê Gestor do IBS lançaram um **Programa Nacional de Conformidade Tributária**, com o objetivo de:\n\n☑ Auxiliar contribuintes com dificuldades para emitir notas fiscais com os destaques de IBS e CBS\n☑ Reduzir autuações por erros formais durante o período inicial de adaptação\n☑ Oferecer canais de orientação e esclarecimento de dúvidas\n☑ Incentivar a autorregularização antes da aplicação de penalidades\n\n**Importante:** o programa de conformidade não elimina a obrigação de pagar os tributos corretamente — ele é uma rede de apoio para reduzir erros involuntários durante a fase de testes, quando isso é mais esperado.\n\n[Imagem: https://images.unsplash.com/photo-1450101499163-c8848c66ca85?w=800&auto=format&fit=crop]\n\n---\n\n## Seção 4: Cenários Práticos por Setor\n\n### Varejo\n\nMaior desafio: gestão de estoque e PDVs durante a transição, com produtos sujeitos a regras diferentes ao longo dos anos. Oportunidade: simplificação da tributação em vendas interestaduais, hoje um dos maiores desafios do varejo online.\n\n### Indústria\n\nMaior desafio: revisão completa da cadeia de fornecedores para garantir o aproveitamento máximo de créditos. Oportunidade: fim do \"efeito cascata\", que hoje encarece produtos com cadeias produtivas longas.\n\n### Serviços\n\nMaior desafio: adaptação de precificação, já que historicamente pagava menos tributo proporcionalmente (via ISS) em muitos municípios. Oportunidade: mais transparência e previsibilidade tributária em operações interestaduais.\n\n### Agronegócio\n\nMaior desafio: entender os regimes específicos e a alíquota reduzida aplicável a produtos agropecuários. Oportunidade: simplificação de obrigações acessórias hoje fragmentadas entre estados.\n\n[Vídeo: https://www.youtube.com/watch?v=6kpYJyQIJMg]\n\n---\n\n## Seção 5: Regimes Específicos e Erros Comuns a Evitar\n\n### Regimes que merecem atenção redobrada\n\n• **Simples Nacional** — tratamento especial já visto no Módulo 2\n• **Zona Franca de Manaus** — mantém incentivos fiscais específicos mesmo com a redução do IPI a zero para os demais produtos\n• **Saúde, educação e transporte público** — alíquota reduzida em 60%, conforme visto no Módulo 1\n• **Cesta básica nacional** — alíquota zero de IBS e CBS\n\n### Erros comuns que o compliance deve evitar\n\n☑ Achar que a reforma é \"só uma mudança de nome\" dos tributos antigos\n☑ Não atualizar contratos e sistemas a tempo da fase de testes\n☑ Deixar de treinar as equipes fiscal, financeira e comercial\n☑ Ignorar publicações técnicas do Comitê Gestor do IBS\n☑ Não revisar o fluxo de caixa considerando o split payment\n\n[Imagem: https://images.unsplash.com/photo-1553877522-43269d4ea984?w=800&auto=format&fit=crop]\n\n---\n\n## Seção 6: Checklist Final de Compliance\n\nAo final da série de 4 módulos, use este checklist para avaliar a preparação da sua empresa:\n\n☑ Toda a equipe entende os conceitos de IBS, CBS e Imposto Seletivo (Módulo 1)\n☑ Contratos, sistemas e precificação foram revisados (Módulo 2)\n☑ A equipe fiscal/contábil entende créditos e split payment (Módulo 3)\n☑ A empresa conhece o regime de fiscalização e o programa de conformidade (Módulo 4)\n☑ Cenários específicos do setor da empresa foram mapeados\n☑ Existe um responsável designado para acompanhar as próximas fases da transição (2027 a 2033)\n\n---\n\n## Seção 7: Conclusão da Série\n\nParabéns por concluir a série completa sobre a **Reforma Tributária**! Ao longo dos 4 módulos, você percorreu desde os fundamentos até os aspectos mais técnicos e estratégicos da maior mudança tributária brasileira desde 1988.\n\nA reforma será implementada de forma gradual até 2033, e o aprendizado contínuo é essencial — novas normas e esclarecimentos serão publicados pelo Comitê Gestor do IBS e pela Receita Federal ao longo dos próximos anos.\n\nAo concluir a leitura, avance para a avaliação final deste módulo e finalize sua jornada de aprendizado sobre o tema.", "criado_em": "2026-09-17T10:21:24.149025+00:00", "data_limite": null, "departamento_id": null, "descricao": "Módulo final da série. Aborda o papel do Comitê Gestor do IBS na fiscalização, o Programa Nacional de Conformidade Tributária, cenários práticos por setor e um checklist final de compliance para encerrar a jornada de aprendizado sobre a Reforma Tributária.", "duracao_minutos": 75, "empresa_id": null, "id": "43a22cbe-429f-4be1-aeec-d8752167b4b4", "instrutor_id": null, "media_avaliacao": 0, "nivel": "avancado", "nota_minima": 7, "obrigatorio": false, "publicado": true, "tempo_avaliacao_minutos": 30, "thumbnail_url": "https://images.unsplash.com/photo-1521737604893-d14cc237f11d?w=1200&auto=format&fit=crop", "titulo": "Reforma Tributária - Módulo 4: Compliance, Fiscalização e Cenários Setoriais", "total_avaliacoes": 0}]$TREINOS$::json)
AS t(
  id uuid, titulo text, descricao text, conteudo_html text, thumbnail_url text, duracao_minutos int,
  categoria text, nivel text, instrutor_id uuid, empresa_id uuid, departamento_id uuid,
  obrigatorio boolean, publicado boolean, nota_minima int, avaliacao_obrigatoria boolean,
  tempo_avaliacao_minutos int, data_limite timestamptz, media_avaliacao numeric, total_avaliacoes int,
  criado_em timestamptz, atualizado_em timestamptz
);

